{
  "name": "RestoAudit Pro",
  "description": "A high-precision restaurant financial management and forensic audit system with detailed income/expense tracking, CSV import capabilities, and loan account management."
}

export type TransactionType = 'INCOME' | 'EXPENSE';

export type Category = 
  | 'Food COGS' 
  | 'Booze COGS' 
  | 'Decor' 
  | 'R&M' 
  | 'Cleaning' 
  | 'Rental (Operating)' 
  | 'Tenant Income' 
  | 'POS Rental' 
  | 'Bank Charges' 
  | 'Credit Card Fees' 
  | 'Loan Payment'
  | 'Other';

export type PaymentMethod = 'CASH' | 'CARD' | 'ACCOUNT' | 'BANK_TRANSFER';

export interface Transaction {
  id: string;
  date: string; // ISO format
  type: TransactionType;
  category: Category;
  amount: number;
  description: string;
  entity: string; // Supplier name or Tenant name
  paymentMethod: PaymentMethod;
  month: string; // e.g., "2024-08"
}

export interface LoanAccount {
  id: string;
  name: string;
  principal: number;
  interestRate: number;
  startDate: string;
  balance: number;
  history: { date: string; amount: number; type: 'PAYMENT' | 'INTEREST_ACCRUAL' }[];
}

export type AppView = 'DASHBOARD' | 'TRANSACTIONS' | 'REPORTS' | 'AUDIT' | 'LOANS';

import React from 'react';
import { LayoutDashboard, Receipt, FileBarChart, ShieldCheck, Landmark } from 'lucide-react';
import { Category, PaymentMethod } from './types';

export const MONTHS = ['2024-08', '2024-09', '2024-10', '2024-11', '2024-12'];

export const CATEGORIES: Category[] = [
  'Food COGS',
  'Booze COGS',
  'Decor',
  'R&M',
  'Cleaning',
  'Rental (Operating)',
  'Tenant Income',
  'POS Rental',
  'Bank Charges',
  'Credit Card Fees',
  'Loan Payment',
  'Other'
];

export const PAYMENT_METHODS: PaymentMethod[] = ['CASH', 'CARD', 'ACCOUNT', 'BANK_TRANSFER'];

export const NAV_ITEMS = [
  { id: 'DASHBOARD', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
  { id: 'TRANSACTIONS', label: 'Transactions', icon: <Receipt size={20} /> },
  { id: 'REPORTS', label: 'Reports', icon: <FileBarChart size={20} /> },
  { id: 'AUDIT', label: 'Forensic Audit', icon: <ShieldCheck size={20} /> },
  { id: 'LOANS', label: 'Loan Accounts', icon: <Landmark size={20} /> },
] as const;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, AppView, LoanAccount } from './types';
import { NAV_ITEMS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TransactionManager from './components/TransactionManager';
import Reports from './components/Reports';
import AuditSheet from './components/AuditSheet';
import LoanManager from './components/LoanManager';

const INITIAL_TRANSACTIONS: Transaction[] = [];

const INITIAL_LOANS: LoanAccount[] = [
  {
    id: 'loan-1',
    name: 'Primary Business Loan (CapEx)',
    principal: 500000,
    interestRate: 8.5,
    startDate: '2024-01-01',
    balance: 450000,
    history: []
  },
  {
    id: 'loan-2',
    name: 'Short-term Operating Facility',
    principal: 100000,
    interestRate: 12.0,
    startDate: '2024-06-15',
    balance: 85000,
    history: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('resto_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [loans, setLoans] = useState<LoanAccount[]>(() => {
    const saved = localStorage.getItem('resto_loans');
    return saved ? JSON.parse(saved) : INITIAL_LOANS;
  });

  useEffect(() => {
    localStorage.setItem('resto_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('resto_loans', JSON.stringify(loans));
  }, [loans]);

  const addTransactions = (newItems: Transaction[]) => {
    setTransactions(prev => [...prev, ...newItems]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const updateLoan = (updatedLoan: LoanAccount) => {
    setLoans(prev => prev.map(l => l.id === updatedLoan.id ? updatedLoan : l));
  };

  const renderContent = () => {
    switch (view) {
      case 'DASHBOARD':
        return <Dashboard transactions={transactions} loans={loans} />;
      case 'TRANSACTIONS':
        return <TransactionManager transactions={transactions} onAdd={addTransactions} onDelete={deleteTransaction} />;
      case 'REPORTS':
        return <Reports transactions={transactions} />;
      case 'AUDIT':
        return <AuditSheet transactions={transactions} />;
      case 'LOANS':
        return <LoanManager loans={loans} onUpdate={updateLoan} onTransactionAdd={addTransactions} />;
      default:
        return <Dashboard transactions={transactions} loans={loans} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar activeView={view} onNavigate={setView} />
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        <div className="max-w-7xl mx-auto space-y-6">
          <header className="flex justify-between items-center pb-4 border-b border-slate-200">
            <div>
              <h1 className="text-2xl font-bold text-slate-900">RestoAudit Pro</h1>
              <p className="text-slate-500 text-sm">Forensic Restaurant Financial Suite (Aug - Dec 2024)</p>
            </div>
            <div className="flex items-center space-x-2 text-xs font-medium uppercase tracking-wider text-slate-400">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span>Live Database Connected</span>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { AppView } from '../types';
import { NAV_ITEMS } from '../constants';

interface SidebarProps {
  activeView: AppView;
  onNavigate: (view: AppView) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, onNavigate }) => {
  return (
    <aside className="w-64 bg-white border-r border-slate-200 flex flex-col h-full hidden md:flex">
      <div className="p-6">
        <div className="flex items-center space-x-3 mb-8">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg">R</div>
          <span className="text-lg font-bold text-slate-800">AuditPro</span>
        </div>
        <nav className="space-y-1">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id as AppView)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeView === item.id
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm'
                  : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
              }`}
            >
              {item.icon}
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          ))}
        </nav>
      </div>
      <div className="mt-auto p-6 border-t border-slate-100">
        <div className="bg-slate-900 rounded-2xl p-4 text-white">
          <p className="text-xs text-slate-400 mb-1">Current Quarter</p>
          <p className="text-sm font-semibold mb-3">Q3 - Q4 2024</p>
          <div className="w-full bg-slate-700 rounded-full h-1.5 mb-1">
            <div className="bg-indigo-500 h-1.5 rounded-full" style={{ width: '80%' }}></div>
          </div>
          <p className="text-[10px] text-slate-400 text-right">80% Reconciled</p>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Transaction, LoanAccount } from '../types';
import { MONTHS } from '../constants';
import { TrendingUp, TrendingDown, DollarSign, Activity } from 'lucide-react';

interface DashboardProps {
  transactions: Transaction[];
  loans: LoanAccount[];
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, loans }) => {
  const stats = useMemo(() => {
    const totalIncome = transactions.filter(t => t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
    const totalExpense = transactions.filter(t => t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
    const netProfit = totalIncome - totalExpense;
    const margin = totalIncome > 0 ? (netProfit / totalIncome) * 100 : 0;

    const monthlyData = MONTHS.map(month => {
      const inc = transactions.filter(t => t.month === month && t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
      const exp = transactions.filter(t => t.month === month && t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
      return { month: month.split('-')[1] + '/24', income: inc, expense: exp };
    });

    const categoryBreakdown = transactions
      .filter(t => t.type === 'EXPENSE')
      .reduce((acc: any, t) => {
        acc[t.category] = (acc[t.category] || 0) + t.amount;
        return acc;
      }, {});

    const pieData = Object.entries(categoryBreakdown).map(([name, value]) => ({ name, value }));

    return { totalIncome, totalExpense, netProfit, margin, monthlyData, pieData };
  }, [transactions]);

  const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'];

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Gross Income" value={stats.totalIncome} icon={<TrendingUp className="text-emerald-500" />} trend="+4.2%" color="border-emerald-100" />
        <StatCard title="Total Expenses" value={stats.totalExpense} icon={<TrendingDown className="text-rose-500" />} trend="+1.8%" color="border-rose-100" />
        <StatCard title="Net Operating Profit" value={stats.netProfit} icon={<DollarSign className="text-indigo-500" />} trend="+12.1%" color="border-indigo-100" />
        <StatCard title="Operating Margin" value={`${stats.margin.toFixed(1)}%`} icon={<Activity className="text-amber-500" />} trend="Stable" color="border-amber-100" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Income vs Expense Trend</h3>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.monthlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#64748b' }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#64748b' }} tickFormatter={(val) => `R${val / 1000}k`} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="income" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={30} name="Income" />
                <Bar dataKey="expense" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={30} name="Expense" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Expense Breakdown</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stats.pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {stats.pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 space-y-2">
            {stats.pieData.slice(0, 4).map((item: any, idx) => (
              <div key={item.name} className="flex items-center justify-between text-xs">
                <div className="flex items-center space-x-2 text-slate-600">
                  <span className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[idx] }}></span>
                  <span>{item.name}</span>
                </div>
                <span className="font-semibold text-slate-800">R{item.value.toLocaleString()}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, trend, color }: any) => (
  <div className={`bg-white p-5 rounded-2xl border ${color} shadow-sm`}>
    <div className="flex justify-between items-start mb-4">
      <div className="p-2 bg-slate-50 rounded-lg">{icon}</div>
      <span className="text-xs font-medium text-slate-500 bg-slate-100 px-2 py-1 rounded-full">{trend}</span>
    </div>
    <p className="text-sm font-medium text-slate-500">{title}</p>
    <p className="text-2xl font-bold text-slate-900 mt-1">
      {typeof value === 'number' ? `R${value.toLocaleString()}` : value}
    </p>
  </div>
);

export default Dashboard;

import React, { useState } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS } from '../constants';
import { Plus, Upload, Search, Trash2, Filter } from 'lucide-react';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'EXPENSE' as TransactionType,
    category: 'Food COGS' as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'BANK_TRANSFER' as PaymentMethod
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      const newTransactions: Transaction[] = [];

      // Simple CSV Parser Expecting: Date,Type,Category,Amount,Entity,Description,Method
      // Skip Header
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const [date, type, category, amount, entity, description, method] = line.split(',');

        newTransactions.push({
          id: crypto.randomUUID(),
          date: date || new Date().toISOString().split('T')[0],
          type: (type as TransactionType) || 'EXPENSE',
          category: (category as Category) || 'Other',
          amount: parseFloat(amount) || 0,
          entity: entity || 'General',
          description: description || '',
          paymentMethod: (method as PaymentMethod) || 'BANK_TRANSFER',
          month: (date || '').substring(0, 7)
        });
      }
      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    return matchesSearch && matchesMonth;
  }).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search entity, vendor, notes..."
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <select 
              className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm appearance-none cursor-pointer"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <label className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 cursor-pointer transition-all text-sm font-medium shadow-sm">
            <Upload size={18} />
            <span>Import CSV</span>
            <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
          </label>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center space-x-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all text-sm font-medium shadow-sm"
          >
            <Plus size={18} />
            <span>Add Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Date</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Entity / Supplier</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Category</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Method</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Amount</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-4 text-sm text-slate-600 font-medium">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-bold text-slate-900">{t.entity}</span>
                    <span className="text-xs text-slate-400 truncate max-w-[200px]">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${
                    t.type === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'
                  }`}>
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4 text-xs text-slate-500 font-medium">{t.paymentMethod}</td>
                <td className={`px-6 py-4 text-sm font-bold ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString()}
                </td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => onDelete(t.id)}
                    className="p-1.5 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-slate-400 italic">No transactions found for this period.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-900">New Financial Entry</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Type</label>
                  <select 
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as TransactionType})}
                  >
                    <option value="EXPENSE">Expense</option>
                    <option value="INCOME">Income</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Date</label>
                  <input 
                    type="date"
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Category</label>
                <select 
                  className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value as Category})}
                >
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-500 uppercase">Amount (ZAR)</label>
                  <input 
                    type="number"
