import React, { useState } from 'react';
import { LoanAccount, Transaction } from '../types';
import { Plus, Minus, History, Calculator } from 'lucide-react';

interface Props {
  loans: LoanAccount[];
  onUpdate: (loan: LoanAccount) => void;
  onTransactionAdd: (items: Transaction[]) => void;
}

const LoanManager: React.FC<Props> = ({ loans, onUpdate, onTransactionAdd }) => {
  const [paymentAmount, setPaymentAmount] = useState(0);

  const handlePayment = (loan: LoanAccount) => {
    if (paymentAmount <= 0) return;

    const updatedLoan: LoanAccount = {
      ...loan,
      balance: loan.balance - paymentAmount,
      history: [
        ...loan.history,
        { date: new Date().toISOString().split('T')[0], amount: paymentAmount, type: 'PAYMENT' }
      ]
    };

    onUpdate(updatedLoan);

    // Also record as a transaction
    const tx: Transaction = {
      id: crypto.randomUUID(),
      date: new Date().toISOString().split('T')[0],
      type: 'EXPENSE',
      category: 'Loan Payment',
      amount: paymentAmount,
      entity: loan.name,
      description: `Payment towards loan principal.`,
      paymentMethod: 'BANK_TRANSFER',
      month: new Date().toISOString().substring(0, 7)
    };
    onTransactionAdd([tx]);
    setPaymentAmount(0);
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {loans.map(loan => (
          <div key={loan.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-6 space-y-6">
            <div className="flex justify-between items-start">
              <div>
                <h3 className="text-xl font-bold text-slate-900">{loan.name}</h3>
                <p className="text-xs text-slate-500 font-medium uppercase tracking-wider mt-1">Started: {loan.startDate}</p>
              </div>
              <div className="bg-indigo-50 px-3 py-1 rounded-full text-indigo-700 text-xs font-bold">
                {loan.interestRate}% APR
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl text-center">
              <p className="text-xs font-bold text-slate-400 uppercase mb-1">Outstanding Balance</p>
              <p className="text-4xl font-black text-slate-900">R{loan.balance.toLocaleString()}</p>
              <div className="mt-4 flex justify-center space-x-4">
                <div className="text-left">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Principal</p>
                  <p className="text-xs font-bold">R{loan.principal.toLocaleString()}</p>
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div className="text-left">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Paid Off</p>
                  <p className="text-xs font-bold text-emerald-600">R{(loan.principal - loan.balance).toLocaleString()}</p>
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Make a Payment</label>
              <div className="flex space-x-2">
                <input 
                  type="number"
                  placeholder="Amount (ZAR)"
                  className="flex-1 p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  onChange={(e) => setPaymentAmount(parseFloat(e.target.value))}
                />
                <button 
                  onClick={() => handlePayment(loan)}
                  className="bg-indigo-600 text-white px-6 py-3 rounded-xl hover:bg-indigo-700 transition-all font-bold shadow-lg shadow-indigo-100 flex items-center space-x-2"
                >
                  <Plus size={18} />
                  <span>Pay</span>
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <h4 className="text-xs font-bold text-slate-500 uppercase flex items-center space-x-2">
                <History size={14} />
                <span>Recent History</span>
              </h4>
              <div className="space-y-2 max-h-32 overflow-y-auto">
                {loan.history.length > 0 ? (
                  loan.history.map((entry, idx) => (
                    <div key={idx} className="flex justify-between items-center text-xs p-2 bg-slate-50 rounded-lg">
                      <span className="text-slate-500 font-medium">{entry.date}</span>
                      <span className="font-bold text-emerald-600">- R{entry.amount.toLocaleString()}</span>
                    </div>
                  ))
                ) : (
                  <p className="text-xs italic text-slate-400 p-2">No recent payments recorded.</p>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center space-x-6">
        <div className="p-4 bg-indigo-100 text-indigo-600 rounded-2xl">
          <Calculator size={32} />
        </div>
        <div>
          <h4 className="text-lg font-bold text-slate-900">Total Debt Liability</h4>
          <p className="text-3xl font-black text-slate-900">
            R{loans.reduce((acc, l) => acc + l.balance, 0).toLocaleString()}
          </p>
          <p className="text-sm text-slate-500 mt-1">Consolidated view of all active loan accounts including interest accruals.</p>
        </div>
      </div>
    </div>
  );
};

