export type TransactionType = 'INCOME' | 'EXPENSE';

export type Category = 
  // Income Side
  | 'POS Cash'
  | 'POS Card'
  | 'Account Sales'
  | 'Tenant Income'
  // Cost of Goods (GOBD/Suppliers)
  | 'Food COGS (GOBD)' 
  | 'Booze COGS (GOBD)' 
  // Operating Expenses
  | 'Decor' 
  | 'R&M' 
  | 'Cleaning Products'
  | 'Petty Cash'
  | 'Staff Wages (Consolidated)'
  | 'Rental (Premises)' 
  // Financial/Admin
  | 'POS Rental' 
  | 'Bank Charges' 
  | 'Credit Card Fees' 
  | 'Loan Payment'
  | 'Other';

export type PaymentMethod = 'CASH' | 'CARD' | 'ACCOUNT' | 'BANK_TRANSFER' | 'PETTY_CASH_TILL';

export interface Transaction {
  id: string;
  date: string; // ISO format
  type: TransactionType;
  category: Category;
  amount: number;
  description: string;
  entity: string; // Supplier name, Tenant name, or Staff Dept
  paymentMethod: PaymentMethod;
  month: string; // e.g., "2024-08"
}

export interface LoanAccount {
  id: string;
  name: string;
  principal: number;
  interestRate: number;
  startDate: string;
  balance: number;
  history: { date: string; amount: number; type: 'PAYMENT' | 'INTEREST_ACCRUAL' }[];
}

export type AppView = 'DASHBOARD' | 'TRANSACTIONS' | 'REPORTS' | 'AUDIT' | 'LOANS';

