                          <div className="flex flex-col">
                            <span className={`text-sm font-bold ${item?.amount ? (isIncome ? 'text-emerald-600' : 'text-slate-900') : 'text-slate-200'}`}>
                              {item?.amount ? `R${item.amount.toLocaleString()}` : '0.00'}
                            </span>
                            {item?.count ? (
                              <span className="text-[10px] text-slate-400 mt-1 flex items-center justify-center space-x-1">
                                <Info size={10} className="text-indigo-400" />
                                <span>{item.count} items</span>
                              </span>
                            ) : null}
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </React.Fragment>
            ))}

            <tr className="bg-emerald-50">
              <td className="sticky left-0 bg-emerald-50 p-5 font-black text-xs border-r border-emerald-100 shadow-sm z-10 text-emerald-800 uppercase tracking-widest">GROSS MONTHLY INCOME</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-5 text-center text-sm font-black text-emerald-700">
                  R{col.totalIncome.toLocaleString()}
                </td>
              ))}
            </tr>
            <tr className="bg-rose-50">
              <td className="sticky left-0 bg-rose-50 p-5 font-black text-xs border-r border-rose-100 shadow-sm z-10 text-rose-800 uppercase tracking-widest">TOTAL EXPENDITURE</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-5 text-center text-sm font-black text-rose-700">
                  R{col.totalExpense.toLocaleString()}
                </td>
              ))}
            </tr>
            <tr className="bg-indigo-900 text-white">
              <td className="sticky left-0 bg-indigo-900 p-6 font-black text-sm border-r border-indigo-700 z-10 uppercase tracking-widest">NET AUDIT SURPLUS</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-6 text-center text-lg font-black tracking-tight">
                  R{col.net.toLocaleString()}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-indigo-50 border border-indigo-100 p-5 rounded-2xl flex items-start space-x-4">
          <CheckCircle2 className="text-indigo-600 shrink-0" size={20} />
          <div>
            <h4 className="text-indigo-900 font-bold text-sm">Petty Cash Protocol</h4>
            <p className="text-indigo-800 text-xs mt-1 leading-relaxed">
              Petty cash entries are audited against daily till slip reconciliations. 
              Ensure all manual petty cash slips are scanned and attached to the monthly journal.
            </p>
          </div>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 p-5 rounded-2xl flex items-start space-x-4">
          <AlertCircle className="text-emerald-600 shrink-0" size={20} />
          <div>
            <h4 className="text-emerald-900 font-bold text-sm">Staff Wage Consolidation</h4>
            <p className="text-emerald-800 text-xs mt-1 leading-relaxed">
              Consolidated wages reflect net pay plus statutory contributions. 
              Breakdowns per department (Kitchen/Floor/Management) are available in the Reports section.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuditSheet;

import React, { useState } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, Info } from 'lucide-react';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'EXPENSE' as TransactionType,
    category: 'Food COGS (GOBD)' as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'BANK_TRANSFER' as PaymentMethod
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      const newTransactions: Transaction[] = [];

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const [date, type, category, amount, entity, description, method] = line.split(',').map(s => s?.trim());

        let inferredCategory = category as Category;
        // Basic heuristic for auto-categorization from descriptions if category is missing
        if (!category && description) {
          const descLower = description.toLowerCase();
          if (descLower.includes('petty')) inferredCategory = 'Petty Cash';
          else if (descLower.includes('wage') || descLower.includes('salary')) inferredCategory = 'Staff Wages (Consolidated)';
          else if (descLower.includes('invoice') || descLower.includes('delivery')) inferredCategory = 'Food COGS (GOBD)';
          else if (descLower.includes('cash') && type === 'INCOME') inferredCategory = 'POS Cash';
        }

        newTransactions.push({
          id: crypto.randomUUID(),
          date: date || new Date().toISOString().split('T')[0],
          type: (type as TransactionType) || 'EXPENSE',
          category: inferredCategory || 'Other',
          amount: parseFloat(amount) || 0,
          entity: entity || 'General',
          description: description || '',
          paymentMethod: (method as PaymentMethod) || 'BANK_TRANSFER',
          month: (date || '').substring(0, 7)
        });
      }
      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    return matchesSearch && matchesMonth;
  }).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="space-y-4">
      <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl flex items-center space-x-3">
        <Info className="text-amber-600" size={20} />
        <p className="text-xs text-amber-800 font-medium">
          <strong>Smart Import:</strong> When uploading CSVs for Wages, Petty Cash, or GOBD Invoices, our system now auto-detects categories based on keywords in your descriptions.
        </p>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search journals, vendors, wages..."
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <select 
              className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm appearance-none cursor-pointer pr-8"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <label className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 cursor-pointer transition-all text-sm font-medium shadow-sm">
            <Upload size={18} />
            <span>Import CSV</span>
            <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
          </label>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center space-x-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all text-sm font-medium shadow-sm"
          >
            <Plus size={18} />
            <span>New Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Date</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Entity / Dept</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Category</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Method</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">Amount</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-4 text-sm text-slate-500 font-medium whitespace-nowrap">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-bold text-slate-900">{t.entity}</span>
                    <span className="text-[10px] text-slate-400 truncate max-w-[250px]">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-lg text-[10px] font-bold border ${
                    t.type === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-indigo-50 text-indigo-700 border-indigo-100'
                  }`}>
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] text-slate-400 font-bold uppercase">{t.paymentMethod}</span>
                </td>
                <td className={`px-6 py-4 text-sm font-black text-right ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => onDelete(t.id)}
                    className="p-1.5 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-16 text-center text-slate-400 italic">No reconciled transactions found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900">Manual Financial Entry</h3>
                <p className="text-xs text-slate-500 mt-0.5">Record Petty Cash, Wages, or GOBD Journal items.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Type</label>
                  <select 
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as TransactionType})}
                  >
                    <option value="EXPENSE">Expense</option>
                    <option value="INCOME">Income</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Date</label>
                  <input 
                    type="date"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Category</label>
                <select 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value as Category})}
                >
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Amount (ZAR)</label>
                  <input 
                    type="number"
                    step="0.01"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-black outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Method</label>
                  <select 
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.paymentMethod}
                    onChange={e => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}
                  >
                    {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Entity (Supplier/Staff Dept/Tenant)</label>
                <input 
                  type="text"
                  placeholder="e.g. Kitchen Wages, Petty Cash Till A, SAB"
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.entity}
                  onChange={e => setFormData({...formData, entity: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Reference / Notes</label>
                <textarea 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium outline-none h-20 resize-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Invoice #, Delivery Note #, Wage Week Ending..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>
              <div className="pt-4 flex space-x-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 transition-all font-bold text-sm"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all font-bold text-sm shadow-xl shadow-indigo-100"
                >
                  Record Entry
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TransactionManager;

import React, { useMemo } from 'react';
import { Transaction, Category } from '../types';
import { MONTHS, CATEGORIES } from '../constants';
// Added ShieldCheck to the imports from lucide-react
import { CheckCircle2, AlertCircle, Info, ShieldCheck } from 'lucide-react';

interface Props {
  transactions: Transaction[];
}

const AuditSheet: React.FC<Props> = ({ transactions }) => {
  const auditGroups = [
    { name: 'INCOME BREAKDOWN', items: ['POS Cash', 'POS Card', 'Account Sales', 'Tenant Income'] as Category[] },
    { name: 'GOBD & SUPPLIER JOURNALS', items: ['Food COGS (GOBD)', 'Booze COGS (GOBD)'] as Category[] },
    { name: 'OPERATING EXPENDITURE', items: ['Decor', 'R&M', 'Cleaning Products', 'Petty Cash', 'Staff Wages (Consolidated)', 'Rental (Premises)'] as Category[] },
    { name: 'FINANCIAL & STATUTORY', items: ['POS Rental', 'Bank Charges', 'Credit Card Fees', 'Loan Payment'] as Category[] }
  ];

  const auditGrid = useMemo(() => {
    return MONTHS.map(month => {
      const monthTx = transactions.filter(t => t.month === month);

      const lineItems = CATEGORIES.map(cat => {
        const amount = monthTx.filter(t => t.category === cat).reduce((acc, t) => acc + t.amount, 0);
        const count = monthTx.filter(t => t.category === cat).length;
        return { cat, amount, count };
      });

      const totalIncome = monthTx.filter(t => t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
      const totalExpense = monthTx.filter(t => t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
      const net = totalIncome - totalExpense;

      return { month, lineItems, totalIncome, totalExpense, net };
    });
  }, [transactions]);

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-slate-900 text-white p-8 rounded-3xl relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500 opacity-10 rounded-full -mr-20 -mt-20"></div>
        <div className="relative z-10">
          <div className="flex items-center space-x-3 mb-2">
            <ShieldCheck className="text-indigo-400" size={28} />
            <h2 className="text-2xl font-bold">Monthly Forensic Audit Ledger</h2>
          </div>
          <p className="text-slate-400 text-sm max-w-2xl leading-relaxed">
            A granular cross-period audit comparing POS-reported income (Cash/Card/Account) against 
            consolidated staff wages, petty cash disbursements, and supplier GOBD journals.
          </p>
        </div>
      </div>

      <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-xl scrollbar-hide">
        <table className="w-full border-collapse">
          <thead>
            <tr>
              <th className="sticky left-0 bg-slate-50 p-6 text-left border-r border-slate-200 z-20 min-w-[240px]">
                <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Financial Department</span>
              </th>
              {auditGrid.map(col => (
                <th key={col.month} className="p-6 bg-slate-50 border-b border-slate-200 text-center min-w-[160px]">
                  <p className="text-sm font-black text-slate-900 uppercase tracking-tighter">{col.month.split('-')[1]} / 2024</p>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {auditGroups.map((group, gIdx) => (
              <React.Fragment key={group.name}>
                <tr className="bg-slate-100/50">
                  <td className="sticky left-0 bg-slate-100/50 p-3 pl-6 text-[10px] font-black text-slate-500 uppercase tracking-widest border-r border-slate-200 z-10" colSpan={1}>
                    {group.name}
                  </td>
                  {auditGrid.map((_, i) => (
                    <td key={i} className="border-b border-slate-200 bg-slate-100/30"></td>
                  ))}
                </tr>
                {group.items.map(cat => (
                  <tr key={cat} className="hover:bg-slate-50 transition-colors group">
                    <td className="sticky left-0 bg-white p-4 pl-8 text-xs font-semibold text-slate-600 border-r border-slate-100 shadow-sm z-10 group-hover:bg-slate-50">
                      {cat}
                    </td>
                    {auditGrid.map(col => {
                      const item = col.lineItems.find(li => li.cat === cat);
                      const isIncome = group.name === 'INCOME BREAKDOWN';
                      return (
                        <td key={col.month} className="p-4 text-center border-b border-slate-100">
                          <div className="flex flex-col">
                            <span className={`text-sm font-bold ${item?.amount ? (isIncome ? 'text-emerald-600' : 'text-slate-900') : 'text-slate-200'}`}>
                              {item?.amount ? `R${item.amount.toLocaleString()}` : '0.00'}
                            </span>
                            {item?.count ? (
                              <span className="text-[10px] text-slate-400 mt-1 flex items-center justify-center space-x-1">
                                <Info size={10} className="text-indigo-400" />
                                <span>{item.count} items</span>
                              </span>
                            ) : null}
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </React.Fragment>
            ))}

            <tr className="bg-emerald-50">
              <td className="sticky left-0 bg-emerald-50 p-5 font-black text-xs border-r border-emerald-100 shadow-sm z-10 text-emerald-800 uppercase tracking-widest">GROSS MONTHLY INCOME</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-5 text-center text-sm font-black text-emerald-700">
                  R{col.totalIncome.toLocaleString()}
                </td>
              ))}
            </tr>
            <tr className="bg-rose-50">
              <td className="sticky left-0 bg-rose-50 p-5 font-black text-xs border-r border-rose-100 shadow-sm z-10 text-rose-800 uppercase tracking-widest">TOTAL EXPENDITURE</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-5 text-center text-sm font-black text-rose-700">
                  R{col.totalExpense.toLocaleString()}
                </td>
              ))}
            </tr>
            <tr className="bg-indigo-900 text-white">
              <td className="sticky left-0 bg-indigo-900 p-6 font-black text-sm border-r border-indigo-700 z-10 uppercase tracking-widest">NET AUDIT SURPLUS</td>
              {auditGrid.map(col => (
                <td key={col.month} className="p-6 text-center text-lg font-black tracking-tight">
                  R{col.net.toLocaleString()}
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-indigo-50 border border-indigo-100 p-5 rounded-2xl flex items-start space-x-4">
          <CheckCircle2 className="text-indigo-600 shrink-0" size={20} />
          <div>
            <h4 className="text-indigo-900 font-bold text-sm">Petty Cash Protocol</h4>
            <p className="text-indigo-800 text-xs mt-1 leading-relaxed">
              Petty cash entries are audited against daily till slip reconciliations. 
              Ensure all manual petty cash slips are scanned and attached to the monthly journal.
            </p>
          </div>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 p-5 rounded-2xl flex items-start space-x-4">
          <AlertCircle className="text-emerald-600 shrink-0" size={20} />
          <div>
            <h4 className="text-emerald-900 font-bold text-sm">Staff Wage Consolidation</h4>
            <p className="text-emerald-800 text-xs mt-1 leading-relaxed">
              Consolidated wages reflect net pay plus statutory contributions. 
              Breakdowns per department (Kitchen/Floor/Management) are available in the Reports section.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuditSheet;

export type TransactionType = 'INCOME' | 'EXPENSE';

export type Category = 
  // Income Side
  | 'POS Cash'
  | 'POS Card'
  | 'Account Sales'
  | 'Tenant Income'
  // GOBD / Supplier COGS
  | 'Food COGS (GOBD)' 
  | 'Booze COGS (GOBD)' 
  | 'Tobacco/Other COGS'
  // Operating Expenses (From Petty Cash / Journals)
  | 'General Expenses'
  | 'Cleaning Products'
  | 'R&M' 
  | 'Gas'
  | 'Electricity & Water'
  | 'Printing & Stationery'
  | 'Rent Paid'
  | 'Staff Wages (Consolidated)'
  | 'Staff Welfare'
  | 'Security'
  | 'Computer Expenses'
  | 'POS Rental' 
  | 'Bank Charges' 
  | 'Credit Card Fees' 
  | 'Loan Payment'
  | 'Other';

export type PaymentMethod = 'CASH' | 'CARD' | 'EFT' | 'ACCOUNT' | 'PETTY_CASH';

export interface Transaction {
  id: string;
  date: string; // ISO format YYYY-MM-DD
  type: TransactionType;
  category: Category;
  amount: number;
  description: string;
  entity: string; // Supplier name, Employee name, etc.
  paymentMethod: PaymentMethod;
  month: string; // YYYY-MM
}

export interface LoanAccount {
  id: string;
  name: string;
  principal: number;
  interestRate: number;
  startDate: string;
  balance: number;
  history: { date: string; amount: number; type: 'PAYMENT' | 'INTEREST_ACCRUAL' }[];
}

export type AppView = 'DASHBOARD' | 'TRANSACTIONS' | 'REPORTS' | 'AUDIT' | 'LOANS';

import React, { useState } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, Info, FileSpreadsheet, Users, Wallet } from 'lucide-react';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'EXPENSE' as TransactionType,
    category: 'Food COGS (GOBD)' as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
  };

  const excelDateToIso = (serial: number) => {
    const date = new Date((serial - 25569) * 86400 * 1000);
    return date.toISOString().split('T')[0];
  };

  const mapCategoryFromDesc = (desc: string): Category => {
    const d = desc.toLowerCase();
    if (d.includes('17 - general')) return 'General Expenses';
    if (d.includes('6 - cleaning')) return 'Cleaning Products';
    if (d.includes('94 - gas')) return 'Gas';
    if (d.includes('31 - printing')) return 'Printing & Stationery';
    if (d.includes('33 - repairs')) return 'R&M';
    if (d.includes('14 - electricity')) return 'Electricity & Water';
    if (d.includes('32 - rent')) return 'Rent Paid';
    if (d.includes('34 - salaries')) return 'Staff Wages (Consolidated)';
    if (d.includes('36 - staff welfare')) return 'Staff Welfare';
    if (d.includes('42 - security')) return 'Security';
    if (d.includes('7 - computer')) return 'Computer Expenses';
    return 'Other';
  };

  const inferGcobdCategory = (supplier: string): Category => {
    const s = supplier.toLowerCase();
    const boozeSuppliers = ['domaine', 'spirits', 'distriliq', 'lismore', ' Gabrielskloof', 'hermanus liquors', 'market liquors', 'frosty whale', 'beaumont', 'creation wine', 'raka', 'delphin', 'newton johnson', 'bouchard', 'arabella', 'village vino', 'thiart', 'nitida'];
    if (boozeSuppliers.some(b => s.includes(b.toLowerCase().trim()))) return 'Booze COGS (GOBD)';
    return 'Food COGS (GOBD)';
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const header = lines[0].toLowerCase();
      const newTransactions: Transaction[] = [];

      // TYPE 1: GOBD (Contains "Grv No" or "Order No")
      if (header.includes('grv no') || header.includes('order no')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          // Columns: Date&Time, User, Supplier, Order No, Grv No, Invoice No, Transaction Type, Total(excl), Tax, Total(incl)
          const excelDate = parseFloat(parts[0]);
          const supplier = parts[2] || 'Unknown';
          const amount = parseFloat(parts[9]) || 0;
          const isoDate = excelDateToIso(excelDate);

          newTransactions.push({
            id: crypto.randomUUID(),
            date: isoDate,
            type: 'EXPENSE',
            category: inferGcobdCategory(supplier),
            amount: Math.abs(amount),
            entity: supplier,
            description: `GRV ${parts[4]} | Invoice ${parts[5]}`,
            paymentMethod: 'ACCOUNT',
            month: isoDate.substring(0, 7)
          });
        }
      } 
      // TYPE 2: Petty Cash / Expenses (Contains "Processed" or "Amount Incl")
      else if (header.includes('amount incl') || header.includes('processed')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          // Columns: Date, Description, Supplier, Invoice No, Amount Excl, Tax, Amount Incl, Payment Type, Processed
          const dateParts = parts[0].split('/');
          const isoDate = dateParts.length === 3 ? `${dateParts[2]}-${dateParts[1].padStart(2, '0')}-${dateParts[0].padStart(2, '0')}` : parts[0];
          const amount = parseFloat(parts[6]) || 0;
          const payMethod = (parts[7]?.toUpperCase() || 'EFT') as PaymentMethod;

          newTransactions.push({
            id: crypto.randomUUID(),
            date: isoDate,
            type: 'EXPENSE',
            category: mapCategoryFromDesc(parts[1]),
            amount: amount,
            entity: parts[2] || 'Various',
            description: parts[1] || '',
            paymentMethod: payMethod,
            month: isoDate.substring(0, 7)
          });
        }
      }
      // TYPE 3: Staff Wages (Contains "Regular Pay" or "Overtime Pay")
      else if (header.includes('regular pay') || header.includes('total pay')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          // Columns: Employee, Job Title, Hours, OT, Rate, RegPay, OTPay, TotalPay, TotalTips
          const employee = parts[0];
          const totalPay = parseFloat(parts[7]) || 0;
          if (totalPay === 0) continue;

          const today = new Date().toISOString().split('T')[0];
          newTransactions.push({
            id: crypto.randomUUID(),
            date: today,
            type: 'EXPENSE',
            category: 'Staff Wages (Consolidated)',
            amount: totalPay,
            entity: employee,
            description: `Wages for ${parts[1]}`,
            paymentMethod: 'EFT',
            month: today.substring(0, 7)
          });
        }
      }

      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    return matchesSearch && matchesMonth;
  }).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="bg-indigo-50 border border-indigo-100 p-3 rounded-xl flex items-center space-x-3">
          <FileSpreadsheet className="text-indigo-600" size={20} />
          <div className="text-[10px] leading-tight font-medium text-indigo-800 uppercase">
            <strong>GOBD Import</strong><br/>Detects Booze vs Food via Supplier name.
          </div>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center space-x-3">
          <Wallet className="text-emerald-600" size={20} />
          <div className="text-[10px] leading-tight font-medium text-emerald-800 uppercase">
            <strong>Petty Cash</strong><br/>Maps numeric prefixes to departments.
          </div>
        </div>
        <div className="bg-amber-50 border border-amber-100 p-3 rounded-xl flex items-center space-x-3">
          <Users className="text-amber-600" size={20} />
          <div className="text-[10px] leading-tight font-medium text-amber-800 uppercase">
            <strong>Staff Wages</strong><br/>Aggregates payroll by employee.
          </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search journals, vendors, wages..."
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <select 
              className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm appearance-none cursor-pointer pr-8"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <label className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 cursor-pointer transition-all text-sm font-medium shadow-sm">
            <Upload size={18} />
            <span>Smart Import</span>
            <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
          </label>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center space-x-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all text-sm font-medium shadow-sm"
          >
            <Plus size={18} />
            <span>Manual Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entity / Source</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Category</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Method</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Amount (ZAR)</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-4 text-xs text-slate-500 font-bold whitespace-nowrap">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-black text-slate-900 leading-none">{t.entity}</span>
                    <span className="text-[10px] text-slate-400 truncate max-w-[300px] mt-1">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-lg text-[10px] font-black border uppercase tracking-tighter ${
                    t.type === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-indigo-50 text-indigo-700 border-indigo-100'
                  }`}>
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{t.paymentMethod}</span>
                </td>
                <td className={`px-6 py-4 text-sm font-black text-right ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => onDelete(t.id)}
                    className="p-1.5 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900">Add Manual Entry</h3>
                <p className="text-xs text-slate-500 mt-0.5">Categorize manual expenses or income.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Type</label>
                  <select 
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as TransactionType})}
                  >
                    <option value="EXPENSE">Expense</option>
                    <option value="INCOME">Income</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Date</label>
                  <input 
                    type="date"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Category</label>
                <select 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value as Category})}
                >
                  {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Amount (ZAR)</label>
                  <input 
                    type="number"
                    step="0.01"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-black outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Method</label>
                  <select 
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.paymentMethod}
                    onChange={e => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}
                  >
                    {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Entity (Supplier/Employee/Tenant)</label>
                <input 
                  type="text"
                  placeholder="e.g. SAB Miller, Kitchen Wages"
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.entity}
                  onChange={e => setFormData({...formData, entity: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Reference / Description</label>
                <textarea 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium outline-none h-20 resize-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Invoice #, Month, Ref..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>
              <div className="pt-4 flex space-x-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 transition-all font-bold text-sm"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all font-bold text-sm shadow-xl shadow-indigo-100"
                >
                  Save Entry
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TransactionManager;

import React, { useMemo } from 'react';
import { Transaction, Category } from '../types';
import { MONTHS, CATEGORIES } from '../constants';
import { CheckCircle2, AlertCircle, Info, ShieldCheck } from 'lucide-react';

interface Props {
  transactions: Transaction[];
}

const AuditSheet: React.FC<Props> = ({ transactions }) => {
  const auditGroups = [
    { name: 'INCOME (POS & REVENUE)', items: ['POS Cash', 'POS Card', 'Account Sales', 'Tenant Income'] as Category[] },
    { name: 'GOBD & SUPPLIER JOURNALS (COGS)', items: ['Food COGS (GOBD)', 'Booze COGS (GOBD)', 'Tobacco/Other COGS'] as Category[] },
    { name: 'OPERATING EXPENDITURE (OPEX)', items: ['General Expenses', 'Cleaning Products', 'R&M', 'Gas', 'Electricity & Water', 'Printing & Stationery', 'Rent Paid', 'Staff Wages (Consolidated)', 'Staff Welfare', 'Security', 'Computer Expenses'] as Category[] },
    { name: 'FINANCIAL CHARGES', items: ['POS Rental', 'Bank Charges', 'Credit Card Fees', 'Loan Payment'] as Category[] }
  ];

  const auditGrid = useMemo(() => {
    return MONTHS.map(month => {
      const monthTx = transactions.filter(t => t.month === month);

      const lineItems = CATEGORIES.map(cat => {
        const amount = monthTx.filter(t => t.category === cat).reduce((acc, t) => acc + t.amount, 0);
        const count = monthTx.filter(t => t.category === cat).length;
        return { cat, amount, count };
      });

      const totalIncome = monthTx.filter(t => t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
      const totalExpense = monthTx.filter(t => t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
      const net = totalIncome - totalExpense;

      return { month, lineItems, totalIncome, totalExpense, net };
    });
  }, [transactions]);

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-slate-900 text-white p-8 rounded-3xl relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500 opacity-10 rounded-full -mr-20 -mt-20"></div>
        <div className="relative z-10 flex justify-between items-center">
          <div className="max-w-2xl">
            <div className="flex items-center space-x-3 mb-2">
              <ShieldCheck className="text-indigo-400" size={28} />
              <h2 className="text-2xl font-black uppercase tracking-tighter">Forensic Audit Ledger</h2>
            </div>
            <p className="text-slate-400 text-sm leading-relaxed">
              Consolidated reconcilation of GOBD delivery journals, petty cash expenses, and aggregated staff wages.
              Cross-verify these against monthly bank statements and POS reports.
            </p>
          </div>
          <div className="hidden lg:block bg-white/5 border border-white/10 p-4 rounded-2xl text-center min-w-[150px]">
            <p className="text-[10px] font-black text-indigo-300 uppercase">Audit Status</p>
            <p className="text-xl font-black">RECONCILED</p>
          </div>
        </div>
      </div>

      <div className="overflow-x-auto bg-white rounded-3xl border border-slate-200 shadow-xl scrollbar-hide">
        <table className="w-full border-collapse">
          <thead>
            <tr>
              <th className="sticky left-0 bg-slate-50 p-6 text-left border-r border-slate-200 z-20 min-w-[280px]">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Financial Mapping</span>
              </th>
              {auditGrid.map(col => (
                <th key={col.month} className="p-6 bg-slate-50 border-b border-slate-200 text-center min-w-[160px]">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Month</p>
                  <p className="text-sm font-black text-slate-900 tracking-tighter">{col.month}</p>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {auditGroups.map((group) => (
              <React.Fragment key={group.name}>
                <tr className="bg-slate-100/50">
