  forcedType?: TransactionType;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food COGS (GOBD)') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  // Reset form defaults if forcedType changes
  useEffect(() => {
    if (forcedType) {
      setFormData(prev => ({
        ...prev,
        type: forcedType,
        category: forcedType === 'INCOME' ? 'POS Cash' : 'Food COGS (GOBD)'
      }));
    }
  }, [forcedType]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
  };

  const excelDateToIso = (serial: number) => {
    const date = new Date((serial - 25569) * 86400 * 1000);
    return date.toISOString().split('T')[0];
  };

  const mapCategoryFromDesc = (desc: string): Category => {
    const d = desc.toLowerCase();
    if (d.includes('17 - general')) return 'General Expenses';
    if (d.includes('6 - cleaning')) return 'Cleaning Products';
    if (d.includes('94 - gas')) return 'Gas';
    if (d.includes('31 - printing')) return 'Printing & Stationery';
    if (d.includes('33 - repairs')) return 'R&M';
    if (d.includes('14 - electricity')) return 'Electricity & Water';
    if (d.includes('32 - rent')) return 'Rent Paid';
    if (d.includes('34 - salaries')) return 'Staff Wages (Consolidated)';
    if (d.includes('36 - staff welfare')) return 'Staff Welfare';
    if (d.includes('42 - security')) return 'Security';
    if (d.includes('7 - computer')) return 'Computer Expenses';
    return 'Other';
  };

  const inferGcobdCategory = (supplier: string): Category => {
    const s = supplier.toLowerCase();
    const boozeSuppliers = ['domaine', 'spirits', 'distriliq', 'lismore', 'gabrielskloof', 'hermanus liquors', 'market liquors', 'frosty whale', 'beaumont', 'creation wine', 'raka', 'delphin', 'newton johnson', 'bouchard', 'arabella', 'village vino', 'thiart', 'nitida'];
    if (boozeSuppliers.some(b => s.includes(b.toLowerCase().trim()))) return 'Booze COGS (GOBD)';
    return 'Food COGS (GOBD)';
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const header = lines[0].toLowerCase();
      const newTransactions: Transaction[] = [];

      // TYPE 1: GOBD (Expenditure)
      if (header.includes('grv no') || header.includes('order no')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          const excelDate = parseFloat(parts[0]);
          const supplier = parts[2] || 'Unknown';
          const amount = parseFloat(parts[9]) || 0;
          const isoDate = excelDateToIso(excelDate);

          newTransactions.push({
            id: crypto.randomUUID(),
            date: isoDate,
            type: 'EXPENSE',
            category: inferGcobdCategory(supplier),
            amount: Math.abs(amount),
            entity: supplier,
            description: `GRV ${parts[4]} | Invoice ${parts[5]}`,
            paymentMethod: 'ACCOUNT',
            month: isoDate.substring(0, 7)
          });
        }
      } 
      // TYPE 2: Petty Cash / Expenses (Expenditure)
      else if (header.includes('amount incl') || header.includes('processed')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          const dateParts = parts[0].split('/');
          const isoDate = dateParts.length === 3 ? `${dateParts[2]}-${dateParts[1].padStart(2, '0')}-${dateParts[0].padStart(2, '0')}` : parts[0];
          const amount = parseFloat(parts[6]) || 0;
          const payMethod = (parts[7]?.toUpperCase() || 'EFT') as PaymentMethod;

          newTransactions.push({
            id: crypto.randomUUID(),
            date: isoDate,
            type: 'EXPENSE',
            category: mapCategoryFromDesc(parts[1]),
            amount: amount,
            entity: parts[2] || 'Various',
            description: parts[1] || '',
            paymentMethod: payMethod,
            month: isoDate.substring(0, 7)
          });
        }
      }
      // TYPE 3: Staff Wages (Expenditure)
      else if (header.includes('regular pay') || header.includes('total pay')) {
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const parts = line.split(',');
          const employee = parts[0];
          const totalPay = parseFloat(parts[7]) || 0;
          if (totalPay === 0) continue;

          const today = new Date().toISOString().split('T')[0];
          newTransactions.push({
            id: crypto.randomUUID(),
            date: today,
            type: 'EXPENSE',
            category: 'Staff Wages (Consolidated)',
            amount: totalPay,
            entity: employee,
            description: `Wages for ${parts[1]}`,
            paymentMethod: 'EFT',
            month: today.substring(0, 7)
          });
        }
      }

      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = !forcedType || t.type === forcedType;
    return matchesSearch && matchesMonth && matchesType;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const filteredCategories = CATEGORIES.filter(cat => {
    if (!forcedType) return true;
    const incomeCats = ['POS Cash', 'POS Card', 'Account Sales', 'Tenant Income', 'Other'];
    if (forcedType === 'INCOME') return incomeCats.includes(cat);
    return !incomeCats.includes(cat) || cat === 'Other';
  });

  return (
    <div className="space-y-4 animate-fadeIn">
      <div className="flex items-center space-x-3 mb-2">
        {forcedType === 'INCOME' ? (
          <TrendingUp className="text-emerald-500" size={24} />
        ) : (
          <TrendingDown className="text-rose-500" size={24} />
        )}
        <h2 className="text-xl font-black uppercase tracking-tight text-slate-900">
          {forcedType === 'INCOME' ? 'Income Management' : 'Expenditure Management'}
        </h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        {forcedType === 'INCOME' ? (
          <div className="bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center space-x-3 col-span-3">
            <TrendingUp className="text-emerald-600" size={20} />
            <div className="text-[10px] leading-tight font-medium text-emerald-800 uppercase">
              <strong>Revenue Ledger</strong><br/>Track POS daily takings, account payments, and tenant rental income.
            </div>
          </div>
        ) : (
          <>
            <div className="bg-indigo-50 border border-indigo-100 p-3 rounded-xl flex items-center space-x-3">
              <FileSpreadsheet className="text-indigo-600" size={20} />
              <div className="text-[10px] leading-tight font-medium text-indigo-800 uppercase">
                <strong>GOBD Import</strong><br/>Detects Booze vs Food via Supplier name.
              </div>
            </div>
            <div className="bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center space-x-3">
              <Wallet className="text-emerald-600" size={20} />
              <div className="text-[10px] leading-tight font-medium text-emerald-800 uppercase">
                <strong>Petty Cash</strong><br/>Maps numeric prefixes to departments.
              </div>
            </div>
            <div className="bg-amber-50 border border-amber-100 p-3 rounded-xl flex items-center space-x-3">
              <Users className="text-amber-600" size={20} />
              <div className="text-[10px] leading-tight font-medium text-amber-800 uppercase">
                <strong>Staff Wages</strong><br/>Aggregates payroll by employee.
              </div>
            </div>
          </>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder={`Search ${forcedType === 'INCOME' ? 'sales, tenants...' : 'journals, vendors...'}`}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <select 
              className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm appearance-none cursor-pointer pr-8"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          {forcedType === 'EXPENSE' && (
            <label className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 cursor-pointer transition-all text-sm font-medium shadow-sm">
              <Upload size={18} />
              <span>Smart Import</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
            </label>
          )}
          <button 
            onClick={() => setIsModalOpen(true)}
            className={`flex items-center space-x-2 px-4 py-2 text-white rounded-xl transition-all text-sm font-medium shadow-sm ${
              forcedType === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-indigo-600 hover:bg-indigo-700'
            }`}
          >
            <Plus size={18} />
            <span>{forcedType === 'INCOME' ? 'Add Income' : 'Add Expense'}</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entity / Source</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Category</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Method</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Amount (ZAR)</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-4 text-xs text-slate-500 font-bold whitespace-nowrap">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-black text-slate-900 leading-none">{t.entity}</span>
                    <span className="text-[10px] text-slate-400 truncate max-w-[300px] mt-1">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-lg text-[10px] font-black border uppercase tracking-tighter ${
                    t.type === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-indigo-50 text-indigo-700 border-indigo-100'
                  }`}>
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{t.paymentMethod}</span>
                </td>
                <td className={`px-6 py-4 text-sm font-black text-right ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className="px-6 py-4 text-right">
                  <button 
                    onClick={() => onDelete(t.id)}
                    className="p-1.5 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-slate-400 text-xs italic">
                  No {forcedType?.toLowerCase() || 'transaction'} records found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900">
                  Manual {forcedType === 'INCOME' ? 'Income' : 'Expenditure'} Entry
                </h3>
                <p className="text-xs text-slate-500 mt-0.5">Record individual financial data points.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Type</label>
                  <select 
                    disabled={!!forcedType}
                    className="w-full p-3 bg-slate-100 border border-slate-200 rounded-xl text-sm font-bold outline-none cursor-not-allowed opacity-75"
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as TransactionType})}
                  >
                    <option value="EXPENSE">Expense</option>
                    <option value="INCOME">Income</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Date</label>
                  <input 
                    type="date"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                  />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Category</label>
                <select 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value as Category})}
                >
                  {filteredCategories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Amount (ZAR)</label>
                  <input 
                    type="number"
                    step="0.01"
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-black outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Method</label>
                  <select 
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                    value={formData.paymentMethod}
                    onChange={e => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}
                  >
                    {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">
                  {forcedType === 'INCOME' ? 'Source / Tenant' : 'Entity (Supplier/Employee)'}
                </label>
                <input 
                  type="text"
                  placeholder={forcedType === 'INCOME' ? "e.g. POS Daily, Unit 4 Tenant" : "e.g. SAB Miller, Kitchen Wages"}
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  value={formData.entity}
                  onChange={e => setFormData({...formData, entity: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider">Reference / Description</label>
                <textarea 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium outline-none h-20 resize-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Reference details..."
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                />
              </div>
              <div className="pt-4 flex space-x-3">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 transition-all font-bold text-sm"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className={`flex-1 px-4 py-3 text-white rounded-xl transition-all font-bold text-sm shadow-xl ${
                    forcedType === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100'
                  }`}
                >
                  Save Entry
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TransactionManager;

export type TransactionType = 'INCOME' | 'EXPENSE';

export type Department = 
  | 'COGS'
  | 'Labor'
  | 'Occupancy'
  | 'Direct Operating'
  | 'G&A'
  | 'CAPEX';

export type Category = 
  // Income
  | 'POS Cash' | 'POS Card' | 'Account Sales' | 'Tenant Income'
  // COGS
  | 'Food Costs' | 'Beverage Costs' | 'Paper Goods'
  // Labor
  | 'Wages & Salaries' | 'Payroll Taxes' | 'Employee Benefits' | 'Workers Comp'
  // Occupancy
  | 'Rent/Mortgage' | 'Property Taxes' | 'Utilities' | 'CAM'
  // Direct Operating
  | 'Marketing & Advertising' | 'Technology' | 'Repairs & Maintenance' | 'Licenses & Permits' | 'Insurance' | 'Cleaning & Sanitation'
  // G&A
  | 'Professional Fees' | 'Bank Fees' | 'Office Supplies'
  // CAPEX
  | 'Equipment' | 'Renovations'
  // Other
  | 'Other';

export type PaymentMethod = 'CASH' | 'CARD' | 'EFT' | 'ACCOUNT' | 'PETTY_CASH';

export interface Transaction {
  id: string;
  date: string; 
  type: TransactionType;
  department: Department | 'REVENUE';
  category: Category;
  amount: number;
  description: string;
  entity: string; 
  paymentMethod: PaymentMethod;
  month: string; 
}

export interface LoanAccount {
  id: string;
  name: string;
  principal: number;
  interestRate: number;
  startDate: string;
  balance: number;
  history: { date: string; amount: number; type: 'PAYMENT' | 'INTEREST_ACCRUAL' }[];
}

export type AppView = 'DASHBOARD' | 'INCOME' | 'EXPENDITURE' | 'REPORTS' | 'AUDIT' | 'LOANS';

import React from 'react';
import { LayoutDashboard, TrendingUp, TrendingDown, FileBarChart, ShieldCheck, Landmark } from 'lucide-react';
import { Category, PaymentMethod, Department } from './types';

export const MONTHS = ['2024-08', '2024-09', '2024-10', '2024-11', '2024-12'];

export const DEPARTMENTS: Department[] = ['COGS', 'Labor', 'Occupancy', 'Direct Operating', 'G&A', 'CAPEX'];

export const DEPT_CATEGORIES: Record<Department | 'REVENUE', Category[]> = {
  REVENUE: ['POS Cash', 'POS Card', 'Account Sales', 'Tenant Income'],
  COGS: ['Food Costs', 'Beverage Costs', 'Paper Goods'],
  Labor: ['Wages & Salaries', 'Payroll Taxes', 'Employee Benefits', 'Workers Comp'],
  Occupancy: ['Rent/Mortgage', 'Property Taxes', 'Utilities', 'CAM'],
  'Direct Operating': ['Marketing & Advertising', 'Technology', 'Repairs & Maintenance', 'Licenses & Permits', 'Insurance', 'Cleaning & Sanitation'],
  G&A: ['Professional Fees', 'Bank Fees', 'Office Supplies'],
  CAPEX: ['Equipment', 'Renovations']
};

export const CATEGORIES: Category[] = Object.values(DEPT_CATEGORIES).flat();

export const PAYMENT_METHODS: PaymentMethod[] = ['CASH', 'CARD', 'EFT', 'ACCOUNT', 'PETTY_CASH'];

export const NAV_ITEMS = [
  { id: 'DASHBOARD', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
  { id: 'INCOME', label: 'Income', icon: <TrendingUp size={20} className="text-emerald-500" /> },
  { id: 'EXPENDITURE', label: 'Expenditure', icon: <TrendingDown size={20} className="text-rose-500" /> },
  { id: 'REPORTS', label: 'Reports', icon: <FileBarChart size={20} /> },
  { id: 'AUDIT', label: 'Forensic Audit', icon: <ShieldCheck size={20} /> },
  { id: 'LOANS', label: 'Loan Accounts', icon: <Landmark size={20} /> },
] as const;

import React, { useState, useEffect } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType, Department } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS, DEPARTMENTS, DEPT_CATEGORIES } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, FileSpreadsheet, Users, Wallet, TrendingUp, TrendingDown, ChevronRight } from 'lucide-react';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
  forcedType?: TransactionType;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeDept, setActiveDept] = useState<Department>('COGS');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    department: (forcedType === 'INCOME' ? 'REVENUE' : 'COGS') as Department | 'REVENUE',
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food Costs') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  useEffect(() => {
    if (forcedType === 'INCOME') {
      setFormData(prev => ({ ...prev, type: 'INCOME', department: 'REVENUE', category: 'POS Cash' }));
    } else {
      setFormData(prev => ({ ...prev, type: 'EXPENSE', department: activeDept, category: DEPT_CATEGORIES[activeDept][0] }));
    }
  }, [forcedType, activeDept]);

  const excelDateToIso = (serial: number) => {
    const date = new Date((serial - 25569) * 86400 * 1000);
    return date.toISOString().split('T')[0];
  };

  const smartAnalyzeExpenditure = (desc: string, supplier: string): { dept: Department; cat: Category } => {
    const d = desc.toLowerCase();
    const s = supplier.toLowerCase();

    // COGS Analysis
    const boozeSuppliers = ['spirits', 'liquors', 'wines', 'beer', 'sab', 'distriliq', 'creation', 'raka', 'delphin', 'vine', 'vino'];
    if (boozeSuppliers.some(b => s.includes(b)) || d.includes('booze')) return { dept: 'COGS', cat: 'Beverage Costs' };
    if (s.includes('packtown') || d.includes('packaging') || d.includes('to-go')) return { dept: 'COGS', cat: 'Paper Goods' };
    if (s.includes('food') || s.includes('meat') || s.includes('produce') || s.includes('fish') || s.includes('dairy')) return { dept: 'COGS', cat: 'Food Costs' };

    // Labor Analysis
    if (d.includes('wage') || d.includes('salary') || s.includes('wages')) return { dept: 'Labor', cat: 'Wages & Salaries' };
    if (d.includes('uif') || d.includes('paye') || d.includes('tax')) return { dept: 'Labor', cat: 'Payroll Taxes' };

    // Occupancy Analysis
    if (d.includes('32 - rent') || s.includes('aberdeen')) return { dept: 'Occupancy', cat: 'Rent/Mortgage' };
    if (d.includes('94 - gas') || d.includes('electricity') || s.includes('gas') || s.includes('twk')) return { dept: 'Occupancy', cat: 'Utilities' };

    // Direct Operating Analysis
    if (d.includes('6 - cleaning') || s.includes('caprichem')) return { dept: 'Direct Operating', cat: 'Cleaning & Sanitation' };
    if (d.includes('33 - repairs') || s.includes('these hands') || s.includes('refrigeration')) return { dept: 'Direct Operating', cat: 'Repairs & Maintenance' };
    if (s.includes('lightspeed') || s.includes('wifi') || d.includes('technology')) return { dept: 'Direct Operating', cat: 'Technology' };

    // G&A Analysis
    if (s.includes('bank') || d.includes('charges') || d.includes('fees')) return { dept: 'G&A', cat: 'Bank Fees' };
    if (s.includes('pna') || d.includes('stationery')) return { dept: 'G&A', cat: 'Office Supplies' };

    // CAPEX Analysis
    if (s.includes('banks dealers') || s.includes('mambos') || s.includes('oven')) return { dept: 'CAPEX', cat: 'Equipment' };

    return { dept: 'G&A', cat: 'Other' };
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      const newTransactions: Transaction[] = [];

      const header = lines[0].toLowerCase();

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');

        if (header.includes('grv no')) { // GOBD Format
          const excelDate = parseFloat(parts[0]);
          const supplier = parts[2] || 'Unknown';
          const amount = Math.abs(parseFloat(parts[9]) || 0);
          const isoDate = excelDateToIso(excelDate);
          const { dept, cat } = smartAnalyzeExpenditure('', supplier);

          newTransactions.push({
            id: crypto.randomUUID(), date: isoDate, type: 'EXPENSE', department: dept, category: cat,
            amount, entity: supplier, description: `GRV ${parts[4]} | Inv ${parts[5]}`, paymentMethod: 'ACCOUNT', month: isoDate.substring(0, 7)
          });
        } else if (header.includes('amount incl')) { // Expenses/Petty Cash Format
          const dParts = parts[0].split('/');
          const isoDate = dParts.length === 3 ? `${dParts[2]}-${dParts[1].padStart(2, '0')}-${dParts[0].padStart(2, '0')}` : parts[0];
          const amount = parseFloat(parts[6]) || 0;
          const { dept, cat } = smartAnalyzeExpenditure(parts[1], parts[2]);

          newTransactions.push({
            id: crypto.randomUUID(), date: isoDate, type: 'EXPENSE', department: dept, category: cat,
            amount, entity: parts[2] || 'Various', description: parts[1] || '', paymentMethod: (parts[7] as PaymentMethod) || 'EFT', month: isoDate.substring(0, 7)
          });
        } else if (header.includes('total pay')) { // Staff Wages
          const totalPay = parseFloat(parts[7]) || 0;
          if (totalPay === 0) continue;
          const today = new Date().toISOString().split('T')[0];
          newTransactions.push({
            id: crypto.randomUUID(), date: today, type: 'EXPENSE', department: 'Labor', category: 'Wages & Salaries',
            amount: totalPay, entity: parts[0], description: `Consolidated Pay: ${parts[1]}`, paymentMethod: 'EFT', month: today.substring(0, 7)
          });
        }
      }
      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = t.type === (forcedType || 'EXPENSE');
    const matchesDept = forcedType === 'INCOME' || t.department === activeDept;
    return matchesSearch && matchesMonth && matchesType && matchesDept;
  }).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="space-y-4 animate-fadeIn">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          {forcedType === 'INCOME' ? <TrendingUp className="text-emerald-500" size={24} /> : <TrendingDown className="text-rose-500" size={24} />}
          <h2 className="text-xl font-black uppercase tracking-tight text-slate-900">
            {forcedType === 'INCOME' ? 'Revenue & Income' : 'Expenditure Management'}
          </h2>
        </div>
        {forcedType === 'EXPENSE' && (
          <div className="flex bg-slate-100 p-1 rounded-xl">
            {DEPARTMENTS.map(dept => (
              <button
                key={dept}
                onClick={() => setActiveDept(dept)}
                className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                  activeDept === dept ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {dept}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder={`Search ${activeDept}...`}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <select 
            className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold"
            value={filterMonth}
            onChange={(e) => setFilterMonth(e.target.value)}
          >
            <option value="ALL">All Months</option>
            {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>

        <div className="flex items-center space-x-2">
          {forcedType === 'EXPENSE' && (
            <label className="flex items-center space-x-2 px-4 py-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-xl hover:bg-indigo-100 cursor-pointer transition-all text-sm font-black uppercase">
              <Upload size={16} />
              <span>Smart Import</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
            </label>
          )}
          <button 
            onClick={() => setIsModalOpen(true)}
            className={`flex items-center space-x-2 px-4 py-2 text-white rounded-xl font-black uppercase text-sm ${
              forcedType === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-slate-900 hover:bg-black'
            }`}
          >
            <Plus size={16} />
            <span>Add Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entity / Source</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Category</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Method</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Amount (ZAR)</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-4 text-xs text-slate-500 font-bold">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-black text-slate-900 leading-none">{t.entity}</span>
                    <span className="text-[10px] text-slate-400 truncate max-w-[300px] mt-1">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="inline-flex items-center px-2 py-0.5 rounded-lg text-[9px] font-black border uppercase tracking-tighter bg-slate-50 text-slate-600">
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4 text-[10px] text-slate-400 font-black uppercase">{t.paymentMethod}</td>
                <td className={`px-6 py-4 text-sm font-black text-right ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => onDelete(t.id)} className="p-1 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100">
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900 uppercase">Manual {formData.department} Entry</h3>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">Recording to Strategic Ledger</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Date</label>
                  <input type="date" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Category</label>
                  <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                    {DEPT_CATEGORIES[formData.department].map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Amount (ZAR)</label>
                  <input type="number" step="0.01" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-black" value={formData.amount} onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Method</label>
                  <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.paymentMethod} onChange={e => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}>
                    {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Entity (Vendor / Employee / Source)</label>
                <input type="text" placeholder="e.g. SAB, Kitchen Wages, Unit 5" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.entity} onChange={e => setFormData({...formData, entity: e.target.value})} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Reference / Notes</label>
                <textarea className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium h-20 resize-none" placeholder="Reference details..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
              </div>
              <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-xl font-black uppercase text-sm shadow-xl shadow-slate-100">Record Entry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

