const INITIAL_TRANSACTIONS: Transaction[] = [];

const INITIAL_LOANS: LoanAccount[] = [
  {
    id: 'loan-1',
    name: 'Primary Business Loan (CapEx)',
    principal: 500000,
    interestRate: 8.5,
    startDate: '2025-01-01',
    balance: 450000,
    history: []
  },
  {
    id: 'loan-2',
    name: 'Short-term Operating Facility',
    principal: 100000,
    interestRate: 12.0,
    startDate: '2025-06-15',
    balance: 85000,
    history: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('resto_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [loans, setLoans] = useState<LoanAccount[]>(() => {
    const saved = localStorage.getItem('resto_loans');
    return saved ? JSON.parse(saved) : INITIAL_LOANS;
  });

  useEffect(() => {
    localStorage.setItem('resto_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('resto_loans', JSON.stringify(loans));
  }, [loans]);

  const addTransactions = (newItems: Transaction[]) => {
    setTransactions(prev => [...prev, ...newItems]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const updateLoan = (updatedLoan: LoanAccount) => {
    setLoans(prev => prev.map(l => l.id === updatedLoan.id ? updatedLoan : l));
  };

  const renderContent = () => {
    switch (view) {
      case 'DASHBOARD':
        return <Dashboard transactions={transactions} loans={loans} />;
      case 'INCOME':
        return (
          <TransactionManager 
            transactions={transactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            forcedType="INCOME"
          />
        );
      case 'EXPENDITURE':
        return (
          <TransactionManager 
            transactions={transactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            forcedType="EXPENSE"
          />
        );
      case 'REPORTS':
        return <Reports transactions={transactions} />;
      case 'AUDIT':
        return <AuditSheet transactions={transactions} />;
      case 'LOANS':
        return <LoanManager loans={loans} onUpdate={updateLoan} onTransactionAdd={addTransactions} />;
      default:
        return <Dashboard transactions={transactions} loans={loans} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar activeView={view} onNavigate={setView} />
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        <div className="max-w-7xl mx-auto space-y-6">
          <header className="flex justify-between items-center pb-4 border-b border-slate-200">
            <div>
              <h1 className="text-2xl font-bold text-slate-900">RestoAudit Pro</h1>
              <p className="text-slate-500 text-sm">Forensic Restaurant Financial Suite (Aug - Dec 2025)</p>
            </div>
            <div className="flex items-center space-x-2 text-xs font-medium uppercase tracking-wider text-slate-400">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span>Live Database Connected</span>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType, Department } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS, DEPARTMENTS, DEPT_CATEGORIES } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, FileSpreadsheet, Users, Wallet, TrendingUp, TrendingDown, ChevronRight } from 'lucide-react';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
  forcedType?: TransactionType;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeDept, setActiveDept] = useState<Department>('COGS');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    department: (forcedType === 'INCOME' ? 'REVENUE' : 'COGS') as Department | 'REVENUE',
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food Costs') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  useEffect(() => {
    if (forcedType === 'INCOME') {
      setFormData(prev => ({ ...prev, type: 'INCOME', department: 'REVENUE', category: 'POS Cash' }));
    } else {
      setFormData(prev => ({ ...prev, type: 'EXPENSE', department: activeDept, category: DEPT_CATEGORIES[activeDept][0] }));
    }
  }, [forcedType, activeDept]);

  const excelDateToIso = (serial: number) => {
    // Excel's epoch is 1899-12-30
    const date = new Date((serial - 25569) * 86400 * 1000);
    return date.toISOString().split('T')[0];
  };

  const smartAnalyzeExpenditure = (desc: string, supplier: string): { dept: Department; cat: Category } => {
    const d = desc.toLowerCase();
    const s = supplier.toLowerCase();

    // COGS Analysis
    const boozeSuppliers = ['spirits', 'liquors', 'wines', 'beer', 'sab', 'distriliq', 'creation', 'raka', 'delphin', 'vine', 'vino', 'frosty whale', 'bouchard', 'arabella', 'nitida'];
    if (boozeSuppliers.some(b => s.includes(b)) || d.includes('booze')) return { dept: 'COGS', cat: 'Beverage Costs' };
    if (s.includes('packtown') || d.includes('packaging') || d.includes('to-go')) return { dept: 'COGS', cat: 'Paper Goods' };
    if (s.includes('food') || s.includes('meat') || s.includes('produce') || s.includes('fish') || s.includes('dairy') || s.includes('econo') || s.includes('bidfood')) return { dept: 'COGS', cat: 'Food Costs' };

    // Labor Analysis
    if (d.includes('wage') || d.includes('salary') || s.includes('wages')) return { dept: 'Labor', cat: 'Wages & Salaries' };
    if (d.includes('uif') || d.includes('paye') || d.includes('tax')) return { dept: 'Labor', cat: 'Payroll Taxes' };

    // Occupancy Analysis
    if (d.includes('32 - rent') || s.includes('aberdeen')) return { dept: 'Occupancy', cat: 'Rent/Mortgage' };
    if (d.includes('94 - gas') || d.includes('electricity') || s.includes('gas') || s.includes('twk')) return { dept: 'Occupancy', cat: 'Utilities' };

    // Direct Operating Analysis
    if (d.includes('6 - cleaning') || s.includes('caprichem')) return { dept: 'Direct Operating', cat: 'Cleaning & Sanitation' };
    if (d.includes('33 - repairs') || s.includes('these hands') || s.includes('refrigeration') || s.includes('macs cool')) return { dept: 'Direct Operating', cat: 'Repairs & Maintenance' };
    if (s.includes('lightspeed') || s.includes('wifi') || d.includes('technology')) return { dept: 'Direct Operating', cat: 'Technology' };

    // G&A Analysis
    if (s.includes('bank') || d.includes('charges') || d.includes('fees')) return { dept: 'G&A', cat: 'Bank Fees' };
    if (s.includes('pna') || d.includes('stationery') || s.includes('checkers') || s.includes('ok minimark')) return { dept: 'G&A', cat: 'Office Supplies' };

    // CAPEX Analysis
    if (s.includes('banks dealers') || s.includes('mambos') || s.includes('oven') || s.includes('takealot')) return { dept: 'CAPEX', cat: 'Equipment' };

    return { dept: 'G&A', cat: 'Other' };
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      const newTransactions: Transaction[] = [];

      const header = lines[0].toLowerCase();

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');

        try {
          if (header.includes('grv no')) { // GOBD Format (Excel Dates)
            const excelDate = parseFloat(parts[0]);
            const supplier = parts[2] || 'Unknown';
            const amount = Math.abs(parseFloat(parts[9]) || 0);
            const isoDate = excelDateToIso(excelDate);
            const { dept, cat } = smartAnalyzeExpenditure('', supplier);

            newTransactions.push({
              id: crypto.randomUUID(), date: isoDate, type: 'EXPENSE', department: dept, category: cat,
              amount, entity: supplier, description: `GRV ${parts[4]} | Inv ${parts[5]}`, paymentMethod: 'ACCOUNT', month: isoDate.substring(0, 7)
            });
          } else if (header.includes('amount incl')) { // Petty Cash Format (DMY Dates)
            const dParts = parts[0].split('/');
            const isoDate = dParts.length === 3 ? `${dParts[2]}-${dParts[1].padStart(2, '0')}-${dParts[0].padStart(2, '0')}` : parts[0];
            const amount = parseFloat(parts[6]) || 0;
            const { dept, cat } = smartAnalyzeExpenditure(parts[1], parts[2]);

            newTransactions.push({
              id: crypto.randomUUID(), date: isoDate, type: 'EXPENSE', department: dept, category: cat,
              amount, entity: parts[2] || 'Various', description: parts[1] || '', paymentMethod: (parts[7] as PaymentMethod) || 'EFT', month: isoDate.substring(0, 7)
            });
          } else if (header.includes('total pay')) { // Staff Wages Format
            const totalPay = parseFloat(parts[7]) || 0;
            if (totalPay === 0) continue;
            const today = new Date().toISOString().split('T')[0];
            newTransactions.push({
              id: crypto.randomUUID(), date: today, type: 'EXPENSE', department: 'Labor', category: 'Wages & Salaries',
              amount: totalPay, entity: parts[0], description: `Consolidated Pay: ${parts[1]}`, paymentMethod: 'EFT', month: today.substring(0, 7)
            });
          }
        } catch (err) {
          console.error("Row parse error at line", i, err);
        }
      }
      onAdd(newTransactions);
    };
    reader.readAsText(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.amount <= 0 || !formData.entity) return;

    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };

    onAdd([newTransaction]);
    setIsModalOpen(false);

    setFormData(prev => ({
      ...prev,
      amount: 0,
      entity: '',
      description: ''
    }));
  };

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = t.type === (forcedType || 'EXPENSE');
    const matchesDept = forcedType === 'INCOME' || t.department === activeDept;
    return matchesSearch && matchesMonth && matchesType && matchesDept;
  }).sort((a, b) => b.date.localeCompare(a.date));

  return (
    <div className="space-y-4 animate-fadeIn">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          {forcedType === 'INCOME' ? <TrendingUp className="text-emerald-500" size={24} /> : <TrendingDown className="text-rose-500" size={24} />}
          <h2 className="text-xl font-black uppercase tracking-tight text-slate-900">
            {forcedType === 'INCOME' ? 'Revenue & Income' : 'Expenditure Management'}
          </h2>
        </div>
        {forcedType === 'EXPENSE' && (
          <div className="flex bg-slate-100 p-1 rounded-xl">
            {DEPARTMENTS.map(dept => (
              <button
                key={dept}
                onClick={() => setActiveDept(dept)}
                className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                  activeDept === dept ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {dept}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder={`Search ${activeDept}...`}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-black text-slate-400 uppercase">Period:</span>
            <select 
              className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold cursor-pointer"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          {forcedType === 'EXPENSE' && (
            <label className="flex items-center space-x-2 px-4 py-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-xl hover:bg-indigo-100 cursor-pointer transition-all text-sm font-black uppercase shadow-sm">
              <Upload size={16} />
              <span>Smart Import</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
            </label>
          )}
          <button 
            onClick={() => setIsModalOpen(true)}
            className={`flex items-center space-x-2 px-4 py-2 text-white rounded-xl font-black uppercase text-sm shadow-md transition-all active:scale-95 ${
              forcedType === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-slate-900 hover:bg-black'
            }`}
          >
            <Plus size={16} />
            <span>Add Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entity / Source</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Category</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Method</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Amount (ZAR)</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group animate-fadeIn">
                <td className="px-6 py-4 text-xs text-slate-500 font-bold">{t.date}</td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="text-sm font-black text-slate-900 leading-none">{t.entity}</span>
                    <span className="text-[10px] text-slate-400 truncate max-w-[300px] mt-1">{t.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="inline-flex items-center px-2 py-0.5 rounded-lg text-[9px] font-black border uppercase tracking-tighter bg-slate-50 text-slate-600">
                    {t.category}
                  </span>
                </td>
                <td className="px-6 py-4 text-[10px] text-slate-400 font-black uppercase">{t.paymentMethod}</td>
                <td className={`px-6 py-4 text-sm font-black text-right ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}>
                  {t.type === 'INCOME' ? '+' : '-'} R{t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => onDelete(t.id)} className="p-1 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all">
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-20 text-center">
                  <div className="flex flex-col items-center justify-center space-y-3 opacity-30">
                    <FileSpreadsheet size={48} />
                    <p className="text-sm font-black uppercase tracking-widest">No Records for {filterMonth === 'ALL' ? 'Selected View' : filterMonth}</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900 uppercase">Manual {formData.department} Entry</h3>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">Recording to Strategic Ledger</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Date</label>
                  <input type="date" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Category</label>
                  <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
