import React, { useState, useEffect, useRef } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType, Department } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS, DEPARTMENTS, DEPT_CATEGORIES } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, FileSpreadsheet, Users, Wallet, TrendingUp, TrendingDown, ChevronRight, FileDown, Check, X } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
  onUpdate: (updated: Transaction) => void;
  forcedType?: TransactionType;
}

interface EditCell {
  id: string;
  field: keyof Transaction;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, onUpdate, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeDept, setActiveDept] = useState<Department>('COGS');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  // Inline editing state
  const [editCell, setEditCell] = useState<EditCell | null>(null);
  const [editValue, setEditValue] = useState<any>(null);
  const inputRef = useRef<HTMLInputElement | HTMLSelectElement | null>(null);

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    department: (forcedType === 'INCOME' ? 'REVENUE' : 'COGS') as Department | 'REVENUE',
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food Costs') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  useEffect(() => {
    if (forcedType === 'INCOME') {
      setFormData(prev => ({ ...prev, type: 'INCOME', department: 'REVENUE', category: 'POS Cash' }));
    } else {
      setFormData(prev => ({ ...prev, type: 'EXPENSE', department: activeDept, category: DEPT_CATEGORIES[activeDept][0] }));
    }
  }, [forcedType, activeDept]);

  useEffect(() => {
    if (editCell && inputRef.current) {
      inputRef.current.focus();
    }
  }, [editCell]);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = t.type === (forcedType || 'EXPENSE');
    const matchesDept = forcedType === 'INCOME' || t.department === activeDept;
    return matchesSearch && matchesMonth && matchesType && matchesDept;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const startEdit = (transaction: Transaction, field: keyof Transaction) => {
    setEditCell({ id: transaction.id, field });
    setEditValue(transaction[field]);
  };

  const saveEdit = () => {
    if (!editCell) return;
    const original = transactions.find(t => t.id === editCell.id);
    if (original) {
      const updated = { ...original, [editCell.field]: editValue };
      // If date changed, update the month identifier
      if (editCell.field === 'date') {
        updated.month = (editValue as string).substring(0, 7);
      }
      onUpdate(updated);
    }
    setEditCell(null);
    setEditValue(null);
  };

  const cancelEdit = () => {
    setEditCell(null);
    setEditValue(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') cancelEdit();
  };

  const exportToPDF = () => {
    const doc = new jsPDF();
    const title = forcedType === 'INCOME' ? 'Income Ledger' : `Expenditure Ledger - ${activeDept}`;
    const period = filterMonth === 'ALL' ? 'August - December 2025' : filterMonth;

    doc.setFontSize(18);
    doc.setTextColor(15, 23, 42); 
    doc.text('RestoAudit Pro', 14, 20);

    doc.setFontSize(11);
    doc.setTextColor(100, 116, 139); 
    doc.text(`${title} | Period: ${period}`, 14, 28);

    doc.setFontSize(9);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 34);

    const tableHeaders = [['Date', 'Entity / Source', 'Category', 'Method', 'Amount (ZAR)']];
    const tableData = filtered.map(t => [
      t.date,
      t.entity,
      t.category,
      t.paymentMethod,
      `R${t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}`
    ]);

    const total = filtered.reduce((acc, curr) => acc + curr.amount, 0);

    (doc as any).autoTable({
      startY: 40,
      head: tableHeaders,
      body: tableData,
      foot: [['', '', '', 'TOTAL', `R${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}`]],
      headStyles: { fillStyle: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
      footStyles: { fillStyle: [241, 245, 249], textColor: [15, 23, 42], fontStyle: 'bold' },
      theme: 'striped',
      styles: { fontSize: 8, cellPadding: 3 }
    });

    doc.save(`${title.replace(/\s+/g, '_')}_${period.replace(/\s+/g, '_')}.pdf`);
  };

  const normalizeDate = (rawDate: string): { iso: string, month: string } => {
    if (!rawDate) return { iso: new Date().toISOString().split('T')[0], month: new Date().toISOString().substring(0, 7) };

    // Handle Excel Serial Dates
    if (!isNaN(Number(rawDate)) && rawDate.length > 4) {
      const serial = parseFloat(rawDate);
      const date = new Date((serial - 25569) * 86400 * 1000);
      const iso = date.toISOString().split('T')[0];
      return { iso, month: iso.substring(0, 7) };
    }

    // Try standard parsing
    let date = new Date(rawDate);

    // If invalid, try common restaurant POS formats (DD/MM/YYYY)
    if (isNaN(date.getTime())) {
      const parts = rawDate.split(/[\/\-]/);
      if (parts.length === 3) {
        // Assume DD/MM/YYYY or YYYY/MM/DD
        if (parts[0].length === 4) { // YYYY/MM/DD
           date = new Date(`${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`);
        } else { // DD/MM/YYYY
           date = new Date(`${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`);
        }
      }
    }

    if (isNaN(date.getTime())) {
      const now = new Date();
      return { iso: now.toISOString().split('T')[0], month: now.toISOString().substring(0, 7) };
    }

    const iso = date.toISOString().split('T')[0];
    return { iso, month: iso.substring(0, 7) };
  };

  const smartAnalyzeRevenue = (desc: string, source: string): { cat: Category, method: PaymentMethod } => {
    const d = desc.toLowerCase();
    const s = source.toLowerCase();

    if (s.includes('cash') || d.includes('cash')) return { cat: 'POS Cash', method: 'CASH' };
    if (s.includes('card') || s.includes('visa') || s.includes('mastercard') || s.includes('yoco') || s.includes('zapper')) return { cat: 'POS Card', method: 'CARD' };
    if (s.includes('tenant') || s.includes('rent') || d.includes('lease')) return { cat: 'Tenant Income', method: 'EFT' };
    if (s.includes('account') || s.includes('invoice') || s.includes('creditor')) return { cat: 'Account Sales', method: 'ACCOUNT' };

    return { cat: 'POS Cash', method: 'CASH' };
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const newTransactions: Transaction[] = [];
      const headerRow = lines[0].toLowerCase().split(',');

      // Dynamic column identification
      const findIdx = (keywords: string[]) => headerRow.findIndex(h => keywords.some(k => h.includes(k)));

      const dateIdx = findIdx(['date', 'timestamp', 'created']);
      const txTypeIdx = findIdx(['transaction type', 'type', 'category']); // Priority for Income Entity
      const amountIdx = findIdx(['amount', 'total', 'price', 'value']);
      const descIdx = findIdx(['description', 'note', 'memo', 'reference']);
      const sourceIdx = findIdx(['source', 'entity', 'vendor', 'supplier']);

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');
        try {
          const rawDate = dateIdx !== -1 ? parts[dateIdx] : parts[0];
          const { iso, month } = normalizeDate(rawDate);

          if (forcedType === 'INCOME') {
            // Using "Transaction Type" column for Entity/Source as requested
            // Fallback to source column or 'POS System'
            let entityName = 'POS System';
            if (txTypeIdx !== -1 && parts[txTypeIdx]) {
              entityName = parts[txTypeIdx].trim();
            } else if (sourceIdx !== -1 && parts[sourceIdx]) {
              entityName = parts[sourceIdx].trim();
            }

            const amount = amountIdx !== -1 ? parseFloat(parts[amountIdx]) || 0 : 0;
            const desc = descIdx !== -1 ? parts[descIdx] || '' : '';
            const { cat, method } = smartAnalyzeRevenue(desc, entityName);

            newTransactions.push({
              id: crypto.randomUUID(),
              date: iso,
              type: 'INCOME',
              department: 'REVENUE',
              category: cat,
              amount,
              entity: entityName,
              description: desc,
              paymentMethod: method,
              month: month
            });
          } else {
            // Expenditure Imports
            const amount = amountIdx !== -1 ? Math.abs(parseFloat(parts[amountIdx]) || 0) : 0;
            const entity = sourceIdx !== -1 ? parts[sourceIdx] || 'Supplier' : (parts[1] || 'Supplier');
            const desc = descIdx !== -1 ? parts[descIdx] || '' : '';
            const txType = txTypeIdx !== -1 ? parts[txTypeIdx] || '' : '';

            // Heuristic for department/category if possible
            let dept: Department = 'COGS';
            let cat: Category = 'Food Costs';

            // Labor/Wage Detection Heuristic
            const searchStr = (entity + desc + txType).toLowerCase();
            if (searchStr.includes('wage') || searchStr.includes('salary') || searchStr.includes('payroll')) {
              dept = 'Labor';
              cat = 'Wages & Salaries';
            }

            // Re-use logic for specific known formats
            const headerStr = lines[0].toLowerCase();
            if (headerStr.includes('grv no')) {
               newTransactions.push({
                id: crypto.randomUUID(), date: iso, type: 'EXPENSE', department: 'COGS', category: 'Food Costs',
                amount: Math.abs(parseFloat(parts[9]) || 0), entity: parts[2] || 'Unknown', description: `GRV ${parts[4]}`, paymentMethod: 'ACCOUNT', month: month
              });
            } else if (headerStr.includes('amount incl')) {
              // Re-check for labor in this specific format too
              let currentDept: Department = 'G&A';
              let currentCat: Category = 'Other';
              if (searchStr.includes('wage') || searchStr.includes('salary') || searchStr.includes('payroll')) {
                currentDept = 'Labor';
                currentCat = 'Wages & Salaries';
              }
              newTransactions.push({
                id: crypto.randomUUID(), date: iso, type: 'EXPENSE', department: currentDept, category: currentCat,
                amount: parseFloat(parts[6]) || 0, entity: parts[2] || 'Various', description: parts[1] || '', paymentMethod: (parts[7] as PaymentMethod) || 'EFT', month: month
              });
            } else {
              newTransactions.push({
                id: crypto.randomUUID(), date: iso, type: 'EXPENSE', department: dept, category: cat,
                amount, entity, description: desc, paymentMethod: 'EFT', month: month
              });
            }
          }
        } catch (err) { console.error("Parse Error at Line " + i, err); }
      }
      onAdd(newTransactions);
      e.target.value = '';
    };
    reader.readAsText(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.amount <= 0 || !formData.entity) return;
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
    setFormData(prev => ({ ...prev, amount: 0, entity: '', description: '' }));
  };

  const renderEditControl = (t: Transaction, field: keyof Transaction) => {
    if (field === 'category') {
      const availableCategories = DEPT_CATEGORIES[t.department as Department | 'REVENUE'];
      return (
        <select
          ref={inputRef as any}
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={saveEdit}
          onKeyDown={handleKeyDown}
          className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
        >
          {availableCategories.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      );
    }
    if (field === 'paymentMethod') {
      return (
        <select
          ref={inputRef as any}
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={saveEdit}
          onKeyDown={handleKeyDown}
          className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
        >
          {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      );
    }
    return (
      <input
        ref={inputRef as any}
        type={field === 'amount' ? 'number' : field === 'date' ? 'date' : 'text'}
        value={editValue}
        onChange={(e) => setEditValue(field === 'amount' ? parseFloat(e.target.value) : e.target.value)}
        onBlur={saveEdit}
        onKeyDown={handleKeyDown}
        className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
      />
    );
  };

  return (
    <div className="space-y-4 animate-fadeIn">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          {forcedType === 'INCOME' ? <TrendingUp className="text-emerald-500" size={24} /> : <TrendingDown className="text-rose-500" size={24} />}
          <h2 className="text-xl font-black uppercase tracking-tight text-slate-900">
            {forcedType === 'INCOME' ? 'Revenue & Income' : 'Expenditure Management'}
          </h2>
        </div>
        {forcedType === 'EXPENSE' && (
          <div className="flex bg-slate-100 p-1 rounded-xl">
            {DEPARTMENTS.map(dept => (
              <button
                key={dept}
                onClick={() => setActiveDept(dept)}
                className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                  activeDept === dept ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {dept}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder={`Search ${forcedType === 'INCOME' ? 'Revenue' : activeDept}...`}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-black text-slate-400 uppercase">Period:</span>
            <select 
              className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold cursor-pointer"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <label className={`flex items-center space-x-2 px-4 py-2 border rounded-xl cursor-pointer transition-all text-sm font-black uppercase shadow-sm ${
            forcedType === 'INCOME' 
              ? 'bg-emerald-50 text-emerald-700 border-emerald-100 hover:bg-emerald-100' 
              : 'bg-indigo-50 text-indigo-700 border-indigo-100 hover:bg-indigo-100'
          }`}>
            <Upload size={16} />
            <span>Smart Import</span>
            <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
          </label>
          <button 
            onClick={exportToPDF}
