  {
    id: 'loan-1',
    name: 'Primary Business Loan (CapEx)',
    principal: 500000,
    interestRate: 8.5,
    startDate: '2025-01-01',
    balance: 450000,
    history: []
  },
  {
    id: 'loan-2',
