import React, { useState, useEffect } from 'react';
import { Transaction, AppView, LoanAccount } from './types';
import { NAV_ITEMS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TransactionManager from './components/TransactionManager';
import LoanManager from './components/LoanManager';
import SupplierManager from './components/SupplierManager';
import IncomeSummary from './components/IncomeSummary';

const INITIAL_TRANSACTIONS: Transaction[] = [];

const INITIAL_LOANS: LoanAccount[] = [
  {
    id: 'loan-2',
    name: 'Short-term Operating Facility',
    principal: 100000,
    interestRate: 12.0,
    startDate: '2025-06-15',
    balance: 85000,
    history: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('resto_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [loans, setLoans] = useState<LoanAccount[]>(() => {
    const saved = localStorage.getItem('resto_loans');
    return saved ? JSON.parse(saved) : INITIAL_LOANS;
  });

  useEffect(() => {
    localStorage.setItem('resto_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('resto_loans', JSON.stringify(loans));
  }, [loans]);

  const addTransactions = (newItems: Transaction[]) => {
    setTransactions(prev => [...prev, ...newItems]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const updateTransaction = (updated: Transaction) => {
    setTransactions(prev => prev.map(t => t.id === updated.id ? updated : t));
  };

  const updateLoan = (updatedLoan: LoanAccount) => {
    setLoans(prev => prev.map(l => l.id === updatedLoan.id ? updatedLoan : l));
  };

  const renderContent = () => {
    switch (view) {
      case 'DASHBOARD':
        return <Dashboard transactions={transactions} loans={loans} onNavigate={setView} />;
      case 'INCOME':
        return (
          <TransactionManager 
            transactions={transactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            onUpdate={updateTransaction}
            forcedType="INCOME"
          />
        );
      case 'INCOME_SUMMARY':
        return <IncomeSummary transactions={transactions} />;
      case 'EXPENDITURE':
        return (
          <TransactionManager 
            transactions={transactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            onUpdate={updateTransaction}
            forcedType="EXPENSE"
          />
        );
      case 'SUPPLIERS':
        return <SupplierManager transactions={transactions} />;
      case 'LOANS':
        return <LoanManager loans={loans} onUpdate={updateLoan} onTransactionAdd={addTransactions} />;
      default:
        return <Dashboard transactions={transactions} loans={loans} onNavigate={setView} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar activeView={view} onNavigate={setView} />
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        <div className="max-w-7xl mx-auto space-y-6">
          <header className="flex justify-between items-center pb-4 border-b border-slate-200">
            <div>
              <h1 className="text-2xl font-bold text-slate-900">RestoAudit Pro</h1>
              <p className="text-slate-500 text-sm">Forensic Restaurant Financial Suite (Aug - Dec 2025)</p>
            </div>
            <div className="flex items-center space-x-2 text-xs font-medium uppercase tracking-wider text-slate-400">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span>Live Database Connected</span>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { LoanAccount, Transaction } from '../types';
import { Plus, Minus, History, Calculator, Edit2 } from 'lucide-react';

interface Props {
  loans: LoanAccount[];
  onUpdate: (loan: LoanAccount) => void;
  onTransactionAdd: (items: Transaction[]) => void;
}

interface EditState {
  loanId: string;
  field: keyof LoanAccount;
}

const LoanManager: React.FC<Props> = ({ loans, onUpdate, onTransactionAdd }) => {
  const [paymentAmount, setPaymentAmount] = useState(0);
  const [editState, setEditState] = useState<EditState | null>(null);
  const [editValue, setEditValue] = useState<any>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editState && inputRef.current) {
      inputRef.current.focus();
    }
  }, [editState]);

  const handlePayment = (loan: LoanAccount) => {
    if (paymentAmount <= 0) return;

    const updatedLoan: LoanAccount = {
      ...loan,
      balance: loan.balance - paymentAmount,
      history: [
        ...loan.history,
        { date: new Date().toISOString().split('T')[0], amount: paymentAmount, type: 'PAYMENT' }
      ]
    };

    onUpdate(updatedLoan);

    const tx: Transaction = {
      id: crypto.randomUUID(),
      date: new Date().toISOString().split('T')[0],
      type: 'EXPENSE',
      department: 'G&A',
      category: 'Other',
      amount: paymentAmount,
      entity: loan.name,
      description: `Payment towards loan principal.`,
      paymentMethod: 'EFT',
      month: new Date().toISOString().substring(0, 7)
    };
    onTransactionAdd([tx]);
    setPaymentAmount(0);
  };

  const startEditing = (loan: LoanAccount, field: keyof LoanAccount) => {
    setEditState({ loanId: loan.id, field });
    setEditValue(loan[field]);
  };

  const saveEdit = () => {
    if (!editState) return;
    const loan = loans.find(l => l.id === editState.loanId);
    if (loan) {
      const updatedLoan = { ...loan, [editState.field]: editValue };
      onUpdate(updatedLoan);
    }
    setEditState(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') setEditState(null);
  };

  const renderEditableValue = (loan: LoanAccount, field: keyof LoanAccount, displayValue: string | number, className: string) => {
    const isEditing = editState?.loanId === loan.id && editState?.field === field;

    if (isEditing) {
      return (
        <input
          ref={inputRef}
          type={typeof loan[field] === 'number' ? 'number' : field === 'startDate' ? 'date' : 'text'}
          value={editValue}
          onChange={(e) => setEditValue(typeof loan[field] === 'number' ? parseFloat(e.target.value) : e.target.value)}
          onBlur={saveEdit}
          onKeyDown={handleKeyDown}
          className={`bg-white border-2 border-indigo-400 rounded px-1 outline-none text-slate-900 ${className}`}
        />
      );
    }

    return (
      <span 
        onDoubleClick={() => startEditing(loan, field)}
        className={`cursor-pointer hover:text-indigo-600 transition-colors border-b border-dashed border-transparent hover:border-indigo-300 ${className}`}
        title="Double-click to edit"
      >
        {displayValue}
      </span>
    );
  };

  return (
    <div className="space-y-6">
      <div className="p-3 bg-indigo-50 border-l-4 border-indigo-400 text-[10px] font-black text-indigo-700 uppercase tracking-widest flex items-center space-x-2 rounded-r-lg">
        <Edit2 size={12} />
        <span>Tip: Double-click any text or value to customize the loan terms inline</span>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {loans.map(loan => (
          <div key={loan.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-6 space-y-6">
            <div className="flex justify-between items-start">
              <div className="flex-1 mr-4">
                <h3 className="text-xl font-bold">
                  {renderEditableValue(loan, 'name', loan.name, 'text-slate-900')}
                </h3>
                <p className="text-xs text-slate-500 font-medium uppercase tracking-wider mt-1">
                  Started: {renderEditableValue(loan, 'startDate', loan.startDate, '')}
                </p>
              </div>
              <div className="bg-indigo-50 px-3 py-1 rounded-full text-indigo-700 text-xs font-bold whitespace-nowrap">
                {renderEditableValue(loan, 'interestRate', loan.interestRate, '')}% APR
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl text-center relative group">
              <p className="text-xs font-bold text-slate-400 uppercase mb-1">Outstanding Balance</p>
              <div className="text-4xl font-black">
                R{renderEditableValue(loan, 'balance', loan.balance.toLocaleString(), 'text-slate-900')}
              </div>

              <div className="mt-4 flex justify-center space-x-4">
                <div className="text-left">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Principal</p>
                  <p className="text-xs font-bold">
                    R{renderEditableValue(loan, 'principal', loan.principal.toLocaleString(), '')}
                  </p>
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div className="text-left">
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Paid Off</p>
                  <p className="text-xs font-bold text-emerald-600">R{(loan.principal - loan.balance).toLocaleString()}</p>
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Make a Payment</label>
              <div className="flex space-x-2">
                <input 
                  type="number"
                  placeholder="Amount (ZAR)"
                  value={paymentAmount || ''}
                  className="flex-1 p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                  onChange={(e) => setPaymentAmount(parseFloat(e.target.value))}
                />
                <button 
                  onClick={() => handlePayment(loan)}
                  className="bg-indigo-600 text-white px-6 py-3 rounded-xl hover:bg-indigo-700 transition-all font-bold shadow-lg shadow-indigo-100 flex items-center space-x-2"
                >
                  <Plus size={18} />
                  <span>Pay</span>
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <h4 className="text-xs font-bold text-slate-500 uppercase flex items-center space-x-2">
                <History size={14} />
                <span>Recent History</span>
              </h4>
              <div className="space-y-2 max-h-32 overflow-y-auto scrollbar-thin">
                {loan.history.length > 0 ? (
                  loan.history.slice().reverse().map((entry, idx) => (
                    <div key={idx} className="flex justify-between items-center text-xs p-2 bg-slate-50 rounded-lg animate-fadeIn">
                      <span className="text-slate-500 font-medium">{entry.date}</span>
                      <span className="font-bold text-emerald-600">- R{entry.amount.toLocaleString()}</span>
                    </div>
                  ))
                ) : (
                  <p className="text-xs italic text-slate-400 p-2">No recent payments recorded.</p>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center space-x-6">
        <div className="p-4 bg-indigo-100 text-indigo-600 rounded-2xl">
          <Calculator size={32} />
        </div>
        <div>
          <h4 className="text-lg font-bold text-slate-900">Total Debt Liability</h4>
          <p className="text-3xl font-black text-slate-900">
            R{loans.reduce((acc, l) => acc + l.balance, 0).toLocaleString()}
          </p>
          <p className="text-sm text-slate-500 mt-1">Consolidated view of all active loan accounts including interest accruals.</p>
        </div>
      </div>
    </div>
  );
};

export default LoanManager;

