                  Started: {renderEditableValue(loan, 'startDate', loan.startDate, '')}
                </p>
              </div>
              <div className="bg-indigo-50 px-3 py-1 rounded-full text-indigo-700 text-xs font-bold whitespace-nowrap">
                {renderEditableValue(loan, 'interestRate', loan.interestRate, '')}% APR
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl text-center relative group">
              <p className="text-xs font-bold text-slate-400 uppercase mb-1">Outstanding Balance</p>
