              {/* CSV JURNAL IMPORT BUTTON */}
              <label className="mt-4 flex items-center justify-center space-x-2 w-full py-2.5 bg-white border border-slate-200 rounded-xl text-[10px] font-black uppercase text-indigo-600 cursor-pointer hover:bg-indigo-50 hover:border-indigo-200 transition-all shadow-sm">
