export default LoanManager;

export type TransactionType = 'INCOME' | 'EXPENSE';

export type Department = 
  | 'COGS'
  | 'Labor'
  | 'Occupancy'
  | 'Direct Operating'
  | 'G&A'
  | 'CAPEX';

export type Category = 
  // Income
  | 'POS Cash' | 'POS Card' | 'Account Sales' | 'Tenant Income'
  // COGS
  | 'Food Costs' | 'Beverage Costs' | 'Paper Goods'
  // Labor
  | 'Wages & Salaries' | 'Payroll Taxes' | 'Employee Benefits' | 'Workers Comp'
  // Occupancy
  | 'Rent/Mortgage' | 'Property Taxes' | 'Utilities' | 'CAM'
  // Direct Operating
  | 'Marketing & Advertising' | 'Technology' | 'Repairs & Maintenance' | 'Licenses & Permits' | 'Insurance' | 'Cleaning & Sanitation'
  // G&A
  | 'Professional Fees' | 'Bank Fees' | 'Office Supplies'
  // CAPEX
  | 'Equipment' | 'Renovations'
  // Other
  | 'Other';

export type PaymentMethod = 'CASH' | 'CARD' | 'EFT' | 'ACCOUNT' | 'PETTY_CASH';

export interface Transaction {
  id: string;
  date: string; 
  type: TransactionType;
  department: Department | 'REVENUE';
  category: Category;
  amount: number;
  description: string;
  entity: string; 
  paymentMethod: PaymentMethod;
  month: string; 
}

export interface LoanAccount {
  id: string;
  name: string;
  principal: number;
  interestRate: number;
  startDate: string;
  balance: number;
  history: { 
    date: string; 
    amount: number; 
    type: 'PAYMENT' | 'INTEREST_ACCRUAL';
    description?: string;
  }[];
}

export type AppView = 'DASHBOARD' | 'INCOME' | 'EXPENDITURE' | 'LOANS' | 'SUPPLIERS' | 'INCOME_SUMMARY';

import React, { useState, useRef, useEffect } from 'react';
import { LoanAccount, Transaction } from '../types';
import { Plus, History, Calculator, Edit2, FileSpreadsheet, FileDown, Download, Check, X } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface Props {
  loans: LoanAccount[];
  onUpdate: (loan: LoanAccount) => void;
  onTransactionAdd: (items: Transaction[]) => void;
}

interface EditState {
  loanId: string;
  field: keyof LoanAccount;
}

interface EditHistoryState {
  loanId: string;
  index: number;
  field: string;
}

const LoanManager: React.FC<Props> = ({ loans, onUpdate, onTransactionAdd }) => {
  const [paymentAmount, setPaymentAmount] = useState(0);
  const [editState, setEditState] = useState<EditState | null>(null);
  const [editHistoryState, setEditHistoryState] = useState<EditHistoryState | null>(null);
  const [editValue, setEditValue] = useState<any>(null);
  const [isImporting, setIsImporting] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const historyInputRef = useRef<HTMLInputElement | HTMLSelectElement>(null);

  useEffect(() => {
    if ((editState || editHistoryState) && (inputRef.current || historyInputRef.current)) {
      const target = inputRef.current || historyInputRef.current;
      target?.focus();
    }
  }, [editState, editHistoryState]);

  const handlePayment = (loan: LoanAccount) => {
    if (paymentAmount <= 0) return;

    const updatedLoan: LoanAccount = {
      ...loan,
      balance: loan.balance - paymentAmount,
      history: [
        ...loan.history,
        { 
          date: new Date().toISOString().split('T')[0], 
          amount: paymentAmount, 
          type: 'PAYMENT',
          description: 'Manual repayment'
        }
      ]
    };

    onUpdate(updatedLoan);

    const tx: Transaction = {
      id: crypto.randomUUID(),
      date: new Date().toISOString().split('T')[0],
      type: 'EXPENSE',
      department: 'G&A',
      category: 'Other',
      amount: paymentAmount,
      entity: loan.name,
      description: `Manual payment towards loan principal.`,
      paymentMethod: 'EFT',
      month: new Date().toISOString().substring(0, 7)
    };
    onTransactionAdd([tx]);
    setPaymentAmount(0);
  };

  const handleCsvJurnal = (loan: LoanAccount, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(loan.id);
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const header = lines[0].toLowerCase().split(',');
      const dateIdx = header.findIndex(h => h.includes('date') || h.includes('time'));
      const amountIdx = header.findIndex(h => h.includes('amount') || h.includes('value') || h.includes('payment'));
      const typeIdx = header.findIndex(h => h.includes('type') || h.includes('desc') || h.includes('transaction'));

      let totalPayments = 0;
      const newHistory = [...loan.history];

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');

        const rawAmount = amountIdx !== -1 ? parts[amountIdx] : parts[1];
        const amount = Math.abs(parseFloat(rawAmount?.replace(/[^\d.-]/g, '')) || 0);

        if (amount === 0) continue;

        const rawDate = dateIdx !== -1 ? parts[dateIdx] : parts[0];
        const date = rawDate || new Date().toISOString().split('T')[0];

        const rawType = typeIdx !== -1 ? parts[typeIdx] : 'Loan Transaction';
        const isInterest = rawType.toLowerCase().includes('interest') || rawType.toLowerCase().includes('accrual') || rawType.toLowerCase().includes('fee');

        const entryType = isInterest ? 'INTEREST_ACCRUAL' : 'PAYMENT';

        newHistory.push({ 
          date, 
          amount, 
          type: entryType as 'PAYMENT' | 'INTEREST_ACCRUAL',
          description: rawType 
        });

        if (entryType === 'PAYMENT') {
          totalPayments += amount;
        } else {
          totalPayments -= amount; 
        }
      }

      const updatedLoan: LoanAccount = {
        ...loan,
        balance: loan.balance - totalPayments,
        history: newHistory.sort((a, b) => a.date.localeCompare(b.date))
      };

      onUpdate(updatedLoan);
      setIsImporting(null);
      if (e.target) e.target.value = '';
    };
    reader.readAsText(file);
  };

  const startEditing = (loan: LoanAccount, field: keyof LoanAccount) => {
    setEditState({ loanId: loan.id, field });
    setEditValue(loan[field]);
  };

  const saveEdit = () => {
    if (!editState) return;
    const loan = loans.find(l => l.id === editState.loanId);
    if (loan) {
      const updatedLoan = { ...loan, [editState.field]: editValue };
      onUpdate(updatedLoan);
    }
    setEditState(null);
  };

  const startEditingHistory = (loanId: string, index: number, field: string, value: any) => {
    setEditHistoryState({ loanId, index, field });
    setEditValue(value);
  };

  const saveHistoryEdit = () => {
    if (!editHistoryState) return;
    const loan = loans.find(l => l.id === editHistoryState.loanId);
    if (loan) {
      const newHistory = [...loan.history];
      // Note: history is often displayed reversed, but the index should be relative to original array
      const entry = { ...newHistory[editHistoryState.index], [editHistoryState.field]: editValue };
      newHistory[editHistoryState.index] = entry as any;

      // Recalculate balance based on history
      let newBalance = loan.principal;
      newHistory.forEach(h => {
        if (h.type === 'PAYMENT') newBalance -= h.amount;
        else newBalance += h.amount;
      });

      onUpdate({ ...loan, history: newHistory, balance: newBalance });
    }
    setEditHistoryState(null);
  };

  const exportToCSV = (loan: LoanAccount) => {
    const headers = ['Date', 'Description', 'Type', 'Value (ZAR)'];
    const rows = loan.history.map(h => [
      h.date,
      h.description || 'N/A',
      h.type,
      h.amount
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `${loan.name.replace(/\s+/g, '_')}_Journal.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportToPDF = (loan: LoanAccount) => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('RestoAudit Pro', 14, 20);
    doc.setFontSize(12);
    doc.text(`Loan Journal: ${loan.name}`, 14, 28);
    doc.setFontSize(10);
    doc.text(`Balance: R${loan.balance.toLocaleString()}`, 14, 34);

    const tableHeaders = [['Date', 'Description', 'Type', 'Value (ZAR)']];
    const tableData = loan.history.slice().reverse().map(h => [
      h.date,
      h.description || 'N/A',
      h.type.replace('_', ' '),
      `R${h.amount.toLocaleString()}`
    ]);

    (doc as any).autoTable({
      startY: 40,
      head: tableHeaders,
      body: tableData,
      theme: 'striped',
      headStyles: { fillStyle: [15, 23, 42], textColor: [255, 255, 255] },
    });

    doc.save(`${loan.name.replace(/\s+/g, '_')}_Journal.pdf`);
  };

  const renderEditableValue = (loan: LoanAccount, field: keyof LoanAccount, displayValue: string | number, className: string) => {
    const isEditing = editState?.loanId === loan.id && editState?.field === field;

    if (isEditing) {
      return (
        <input
          ref={inputRef}
          type={typeof loan[field] === 'number' ? 'number' : field === 'startDate' ? 'date' : 'text'}
          value={editValue}
          onChange={(e) => setEditValue(typeof loan[field] === 'number' ? parseFloat(e.target.value) : e.target.value)}
          onBlur={saveEdit}
          onKeyDown={(e) => e.key === 'Enter' && saveEdit()}
          className={`bg-white border-2 border-indigo-400 rounded px-1 outline-none text-slate-900 ${className}`}
        />
      );
    }

    return (
      <span 
        onDoubleClick={() => startEditing(loan, field)}
        className={`cursor-pointer hover:text-indigo-600 transition-colors border-b border-dashed border-transparent hover:border-indigo-300 ${className}`}
        title="Double-click to edit"
      >
        {displayValue}
      </span>
    );
  };

  const renderHistoryCell = (loanId: string, index: number, field: string, value: any, type: 'text' | 'number' | 'date' | 'select' = 'text') => {
    const isEditing = editHistoryState?.loanId === loanId && editHistoryState?.index === index && editHistoryState?.field === field;

    if (isEditing) {
      if (type === 'select') {
        return (
          <select
            ref={historyInputRef as any}
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onBlur={saveHistoryEdit}
            className="w-full text-xs p-0.5 border border-indigo-400 rounded outline-none"
          >
            <option value="PAYMENT">PAYMENT</option>
            <option value="INTEREST_ACCRUAL">INTEREST ACCRUAL</option>
          </select>
        );
      }
      return (
        <input
          ref={historyInputRef as any}
          type={type}
          value={editValue}
          onChange={(e) => setEditValue(type === 'number' ? parseFloat(e.target.value) : e.target.value)}
          onBlur={saveHistoryEdit}
          onKeyDown={(e) => e.key === 'Enter' && saveHistoryEdit()}
          className="w-full text-xs p-0.5 border border-indigo-400 rounded outline-none"
        />
      );
    }

    return (
      <div 
        onDoubleClick={() => startEditingHistory(loanId, index, field, value)}
        className="cursor-pointer hover:bg-indigo-50 px-1 rounded transition-colors"
        title="Double-click to edit"
      >
        {field === 'amount' ? `R${value.toLocaleString()}` : value}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <div className="p-3 bg-indigo-50 border-l-4 border-indigo-400 text-[10px] font-black text-indigo-700 uppercase tracking-widest flex items-center space-x-2 rounded-r-lg">
        <Edit2 size={12} />
        <span>Tip: Double-click any cell in the journal to edit details inline. Balance updates automatically.</span>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {loans.map(loan => (
          <div key={loan.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="space-y-1">
                <h3 className="text-2xl font-black text-slate-900">
                  {renderEditableValue(loan, 'name', loan.name, '')}
                </h3>
                <div className="flex items-center space-x-4">
                  <span className="text-xs text-slate-400 font-bold uppercase tracking-widest">
                    Facility Start: {renderEditableValue(loan, 'startDate', loan.startDate, '')}
                  </span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span className="text-xs text-indigo-600 font-black uppercase tracking-widest">
                    {renderEditableValue(loan, 'interestRate', loan.interestRate, '')}% APR Variable
                  </span>
                </div>
              </div>

              <div className="bg-slate-900 text-white p-6 rounded-2xl flex items-center space-x-8 shadow-xl">
                <div className="text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Live Balance</p>
                  <p className="text-3xl font-black">
                    R{renderEditableValue(loan, 'balance', loan.balance.toLocaleString(), 'text-white')}
                  </p>
                </div>
                <div className="h-10 w-px bg-slate-700"></div>
                <div className="text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Principal</p>
                  <p className="text-xl font-bold text-slate-300">
                    R{renderEditableValue(loan, 'principal', loan.principal.toLocaleString(), 'text-slate-300')}
                  </p>
                </div>
              </div>
            </div>

            <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="space-y-6">
                <div>
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 text-center md:text-left">Journal Control</h4>
                  <div className="space-y-3">
                    <label className="flex items-center justify-center space-x-2 w-full py-4 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-2xl text-xs font-black uppercase cursor-pointer hover:bg-indigo-100 transition-all shadow-sm">
                      <FileSpreadsheet size={18} />
                      <span>{isImporting === loan.id ? 'Extracting Journal...' : 'Import Full CSV Journal'}</span>
                      <input 
                        type="file" 
                        accept=".csv" 
                        className="hidden" 
                        onChange={(e) => handleCsvJurnal(loan, e)}
                        disabled={!!isImporting}
                      />
                    </label>
                    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Manual Paypoint</p>
                       <div className="flex space-x-2">
                        <input 
                          type="number"
                          placeholder="ZAR Amount"
                          className="flex-1 min-w-0 p-3 bg-white border border-slate-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                          value={paymentAmount || ''}
                          onChange={(e) => setPaymentAmount(parseFloat(e.target.value))}
                        />
                        <button 
                          onClick={() => handlePayment(loan)}
                          className="bg-slate-900 text-white px-4 py-3 rounded-xl hover:bg-black transition-all font-black text-xs uppercase"
                        >
                          Pay
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-2 space-y-4">
                <div className="flex justify-between items-center">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center space-x-2">
                    <History size={16} />
                    <span>Detailed Transaction Journal</span>
                  </h4>
                  <div className="flex items-center space-x-2">
                    <button 
                      onClick={() => exportToCSV(loan)}
                      className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition-all flex items-center space-x-1"
                      title="Export to CSV"
                    >
                      <Download size={14} />
                      <span className="text-[9px] font-black uppercase">CSV</span>
                    </button>
                    <button 
                      onClick={() => exportToPDF(loan)}
                      className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 transition-all flex items-center space-x-1"
                      title="Export to PDF"
                    >
                      <FileDown size={14} />
                      <span className="text-[9px] font-black uppercase">PDF</span>
                    </button>
                    <span className="text-[10px] font-bold text-slate-400 uppercase ml-2">{loan.history.length} Records</span>
                  </div>
                </div>

                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden shadow-inner">
                  <div className="max-h-[500px] overflow-y-auto scrollbar-thin">
                    <table className="w-full text-left border-collapse">
                      <thead className="bg-slate-100 sticky top-0 z-10">
                        <tr>
                          <th className="px-4 py-3 text-[9px] font-black text-slate-500 uppercase tracking-widest">Date</th>
                          <th className="px-4 py-3 text-[9px] font-black text-slate-500 uppercase tracking-widest">Description</th>
                          <th className="px-4 py-3 text-[9px] font-black text-slate-500 uppercase tracking-widest">Type</th>
                          <th className="px-4 py-3 text-[9px] font-black text-slate-500 uppercase tracking-widest text-right">Value</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-200">
                        {loan.history.length > 0 ? (
                          [...loan.history].reverse().map((_, revIdx) => {
                            const actualIdx = loan.history.length - 1 - revIdx;
                            const entry = loan.history[actualIdx];
                            return (
                              <tr key={revIdx} className="hover:bg-white transition-colors group">
                                <td className="px-4 py-3 text-xs font-bold text-slate-500 whitespace-nowrap">
                                  {renderHistoryCell(loan.id, actualIdx, 'date', entry.date, 'date')}
                                </td>
                                <td className="px-4 py-3 text-xs font-medium text-slate-600 min-w-[150px]">
                                  {renderHistoryCell(loan.id, actualIdx, 'description', entry.description || 'Account Movement')}
                                </td>
                                <td className="px-4 py-3">
                                  {editHistoryState?.loanId === loan.id && editHistoryState?.index === actualIdx && editHistoryState?.field === 'type' ? (
                                    renderHistoryCell(loan.id, actualIdx, 'type', entry.type, 'select')
                                  ) : (
                                    <span 
                                      onDoubleClick={() => startEditingHistory(loan.id, actualIdx, 'type', entry.type)}
                                      className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-tighter cursor-pointer ${
                                        entry.type === 'PAYMENT' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                                      }`}
                                    >
                                      {entry.type.replace('_', ' ')}
                                    </span>
                                  )}
                                </td>
                                <td className={`px-4 py-3 text-xs font-black text-right whitespace-nowrap ${
                                  entry.type === 'PAYMENT' ? 'text-emerald-600' : 'text-rose-600'
                                }`}>
                                  <div className="flex justify-end items-center space-x-1">
                                    <span>{entry.type === 'PAYMENT' ? '-' : '+'}</span>
                                    {renderHistoryCell(loan.id, actualIdx, 'amount', entry.amount, 'number')}
                                  </div>
                                </td>
                              </tr>
                            );
                          })
                        ) : (
                          <tr>
                            <td colSpan={4} className="px-4 py-10 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest opacity-50">
                              No Journal History Loaded
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-6">
          <div className="p-4 bg-indigo-100 text-indigo-600 rounded-2xl">
            <Calculator size={32} />
          </div>
          <div>
            <h4 className="text-lg font-bold text-slate-900">Total Facility Liability</h4>
            <p className="text-sm text-slate-500">Consolidated audit of all active credit facilities and extracted interest components.</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-3xl font-black text-slate-900">
            R{loans.reduce((acc, l) => acc + l.balance, 0).toLocaleString()}
          </p>
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Audited & Verified</span>
        </div>
      </div>
    </div>
  );
};

export default LoanManager;

import React, { useState, useEffect, useRef } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType, Department } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS, DEPARTMENTS, DEPT_CATEGORIES } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, FileSpreadsheet, Wallet, TrendingUp, TrendingDown, ChevronRight, FileDown, Download, Check, X } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
  onUpdate: (updated: Transaction) => void;
  forcedType?: TransactionType;
}

interface EditCell {
  id: string;
  field: keyof Transaction;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, onUpdate, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeDept, setActiveDept] = useState<Department>('COGS');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [editCell, setEditCell] = useState<EditCell | null>(null);
  const [editValue, setEditValue] = useState<any>(null);
  const inputRef = useRef<HTMLInputElement | HTMLSelectElement | null>(null);

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    department: (forcedType === 'INCOME' ? 'REVENUE' : 'COGS') as Department | 'REVENUE',
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food Costs') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  useEffect(() => {
    if (forcedType === 'INCOME') {
      setFormData(prev => ({ ...prev, type: 'INCOME', department: 'REVENUE', category: 'POS Cash' }));
    } else {
      setFormData(prev => ({ ...prev, type: 'EXPENSE', department: activeDept, category: DEPT_CATEGORIES[activeDept][0] }));
    }
  }, [forcedType, activeDept]);

  useEffect(() => {
    if (editCell && inputRef.current) {
      inputRef.current.focus();
    }
  }, [editCell]);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = t.type === (forcedType || 'EXPENSE');
    const matchesDept = forcedType === 'INCOME' || t.department === activeDept;
    return matchesSearch && matchesMonth && matchesType && matchesDept;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const startEdit = (transaction: Transaction, field: keyof Transaction) => {
    setEditCell({ id: transaction.id, field });
    setEditValue(transaction[field]);
  };

  const saveEdit = () => {
    if (!editCell) return;
    const original = transactions.find(t => t.id === editCell.id);
    if (original) {
      const updated = { ...original, [editCell.field]: editValue };
      if (editCell.field === 'date') {
        updated.month = (editValue as string).substring(0, 7);
      }
      onUpdate(updated);
    }
    setEditCell(null);
    setEditValue(null);
  };

  const cancelEdit = () => {
    setEditCell(null);
    setEditValue(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') cancelEdit();
  };

  const exportToCSV = () => {
    const title = forcedType === 'INCOME' ? 'Income_Ledger' : `Expenditure_Ledger_${activeDept}`;
    const period = filterMonth === 'ALL' ? 'Consolidated' : filterMonth;
    const headers = ['Date', 'Entity', 'Description', 'Category', 'Department', 'Payment Method', 'Amount'];

    const rows = filtered.map(t => [
      t.date,
      `"${t.entity.replace(/"/g, '""')}"`,
      `"${t.description.replace(/"/g, '""')}"`,
      t.category,
      t.department,
      t.paymentMethod,
      t.amount
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `${title}_${period}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportToPDF = () => {
    const doc = new jsPDF();
    const title = forcedType === 'INCOME' ? 'Income Ledger' : `Expenditure Ledger - ${activeDept}`;
    const period = filterMonth === 'ALL' ? 'August - December 2025' : filterMonth;

    doc.setFontSize(18);
    doc.setTextColor(15, 23, 42); 
    doc.text('RestoAudit Pro', 14, 20);

    doc.setFontSize(11);
    doc.setTextColor(100, 116, 139); 
    doc.text(`${title} | Period: ${period}`, 14, 28);

    doc.setFontSize(9);
    doc.text(`Generated: ${new Date().toLocaleString()}`, 14, 34);

    const tableHeaders = [['Date', 'Entity / Source', 'Category', 'Method', 'Amount (ZAR)']];
    const tableData = filtered.map(t => [
      t.date,
      t.entity,
      t.category,
      t.paymentMethod,
      `R${t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}`
    ]);

    const total = filtered.reduce((acc, curr) => acc + curr.amount, 0);

    (doc as any).autoTable({
      startY: 40,
      head: tableHeaders,
      body: tableData,
      foot: [['', '', '', 'TOTAL', `R${total.toLocaleString(undefined, { minimumFractionDigits: 2 })}`]],
      headStyles: { fillStyle: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
      footStyles: { fillStyle: [241, 245, 249], textColor: [15, 23, 42], fontStyle: 'bold' },
      theme: 'striped',
      styles: { fontSize: 8, cellPadding: 3 }
    });

    doc.save(`${title.replace(/\s+/g, '_')}_${period.replace(/\s+/g, '_')}.pdf`);
  };

  const normalizeDate = (rawDate: string): { iso: string, month: string } => {
    if (!rawDate) return { iso: new Date().toISOString().split('T')[0], month: new Date().toISOString().substring(0, 7) };
    if (!isNaN(Number(rawDate)) && rawDate.length > 4) {
      const serial = parseFloat(rawDate);
      const date = new Date((serial - 25569) * 86400 * 1000);
      const iso = date.toISOString().split('T')[0];
      return { iso, month: iso.substring(0, 7) };
    }
    let date = new Date(rawDate);
    if (isNaN(date.getTime())) {
      const parts = rawDate.split(/[\/\-]/);
      if (parts.length === 3) {
        if (parts[0].length === 4) {
           date = new Date(`${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`);
        } else {
           date = new Date(`${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`);
        }
      }
    }
    if (isNaN(date.getTime())) {
      const now = new Date();
      return { iso: now.toISOString().split('T')[0], month: now.toISOString().substring(0, 7) };
    }
    const iso = date.toISOString().split('T')[0];
    return { iso, month: iso.substring(0, 7) };
  };

  const smartAnalyzeRevenue = (desc: string, source: string): { cat: Category, method: PaymentMethod } => {
    const d = desc.toLowerCase();
    const s = source.toLowerCase();
    if (s.includes('cash') || d.includes('cash')) return { cat: 'POS Cash', method: 'CASH' };
    if (s.includes('card') || s.includes('visa') || s.includes('mastercard') || s.includes('yoco') || s.includes('zapper')) return { cat: 'POS Card', method: 'CARD' };
    if (s.includes('tenant') || s.includes('rent') || d.includes('lease')) return { cat: 'Tenant Income', method: 'EFT' };
    if (s.includes('account') || s.includes('invoice') || s.includes('creditor')) return { cat: 'Account Sales', method: 'ACCOUNT' };
    return { cat: 'POS Cash', method: 'CASH' };
  };

  const handleCsvUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const newTransactions: Transaction[] = [];
      const headerRow = lines[0].toLowerCase().split(',');
      const findIdx = (keywords: string[]) => headerRow.findIndex(h => keywords.some(k => h.includes(k)));

      const dateIdx = findIdx(['date', 'timestamp', 'created']);
      const txTypeIdx = findIdx(['transaction type', 'type', 'category', 'dept']);
      const amountIdx = findIdx(['amount', 'total', 'price', 'value', 'incl']);
      const descIdx = findIdx(['description', 'note', 'memo', 'reference']);
      const sourceIdx = findIdx(['source', 'entity', 'vendor', 'supplier']);

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');
        try {
          const rawDate = dateIdx !== -1 ? parts[dateIdx] : parts[0];
          const { iso, month } = normalizeDate(rawDate);

          if (forcedType === 'INCOME') {
            let entityName = 'POS System';
            if (txTypeIdx !== -1 && parts[txTypeIdx]) {
              entityName = parts[txTypeIdx].trim();
            } else if (sourceIdx !== -1 && parts[sourceIdx]) {
              entityName = parts[sourceIdx].trim();
            }
            const amount = amountIdx !== -1 ? parseFloat(parts[amountIdx].replace(/[^\d.-]/g, '')) || 0 : 0;
            const desc = descIdx !== -1 ? parts[descIdx] || '' : '';
            const { cat, method } = smartAnalyzeRevenue(desc, entityName);
            newTransactions.push({
              id: crypto.randomUUID(), date: iso, type: 'INCOME', department: 'REVENUE',
              category: cat, amount, entity: entityName, description: desc, paymentMethod: method, month: month
            });
          } else {
            const amount = amountIdx !== -1 ? Math.abs(parseFloat(parts[amountIdx].replace(/[^\d.-]/g, '')) || 0) : 0;
            const entity = sourceIdx !== -1 ? parts[sourceIdx] || 'Supplier' : (parts[1] || 'Supplier');
            const desc = descIdx !== -1 ? parts[descIdx] || '' : '';
            const txType = txTypeIdx !== -1 ? (parts[txTypeIdx] || '') : '';

            let dept: Department = 'COGS';
            let cat: Category = 'Food Costs';

            const fullContent = (entity + ' ' + desc + ' ' + txType).toLowerCase();
            if (fullContent.includes('wage') || fullContent.includes('salary') || fullContent.includes('labor') || fullContent.includes('payroll')) {
              dept = 'Labor';
              cat = 'Wages & Salaries';
            } else if (fullContent.includes('rent') || fullContent.includes('lease') || fullContent.includes('utility') || fullContent.includes('electric')) {
              dept = 'Occupancy';
              cat = 'Rent/Mortgage';
            }

            newTransactions.push({
              id: crypto.randomUUID(), date: iso, type: 'EXPENSE', department: dept,
              category: cat, amount, entity, description: desc, paymentMethod: 'EFT', month: month
            });
          }
        } catch (err) { console.error("Parse Error at Line " + i, err); }
      }
      onAdd(newTransactions);
      e.target.value = '';
    };
    reader.readAsText(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.amount <= 0 || !formData.entity) return;
    const newTransaction: Transaction = {
      ...formData,
      id: crypto.randomUUID(),
      month: formData.date.substring(0, 7)
    };
    onAdd([newTransaction]);
    setIsModalOpen(false);
    setFormData(prev => ({ ...prev, amount: 0, entity: '', description: '' }));
  };

  const renderEditControl = (t: Transaction, field: keyof Transaction) => {
    if (field === 'category') {
      const availableCategories = DEPT_CATEGORIES[t.department as Department | 'REVENUE'];
      return (
        <select
          ref={inputRef as any}
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={saveEdit}
          onKeyDown={handleKeyDown}
          className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
        >
          {availableCategories.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      );
    }
    if (field === 'paymentMethod') {
      return (
        <select
          ref={inputRef as any}
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={saveEdit}
          onKeyDown={handleKeyDown}
          className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
        >
          {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      );
    }
    return (
      <input
        ref={inputRef as any}
        type={field === 'amount' ? 'number' : field === 'date' ? 'date' : 'text'}
        value={editValue}
        onChange={(e) => setEditValue(field === 'amount' ? parseFloat(e.target.value) : e.target.value)}
        onBlur={saveEdit}
        onKeyDown={handleKeyDown}
        className="w-full p-1 bg-white border border-indigo-400 rounded shadow-sm text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
      />
    );
  };

  return (
    <div className="space-y-4 animate-fadeIn">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        <div className="flex items-center space-x-3">
          {forcedType === 'INCOME' ? <TrendingUp className="text-emerald-500" size={24} /> : <TrendingDown className="text-rose-500" size={24} />}
          <h2 className="text-xl font-black uppercase tracking-tight text-slate-900">
            {forcedType === 'INCOME' ? 'Revenue & Income' : 'Expenditure Management'}
          </h2>
        </div>
        {forcedType === 'EXPENSE' && (
          <div className="flex bg-slate-100 p-1 rounded-xl overflow-x-auto whitespace-nowrap">
            {DEPARTMENTS.map(dept => (
              <button
                key={dept}
                onClick={() => setActiveDept(dept)}
                className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                  activeDept === dept ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {dept}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-3 flex-1">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder={`Search ${forcedType === 'INCOME' ? 'Revenue' : activeDept}...`}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center space-x-2">
            <span className="text-[10px] font-black text-slate-400 uppercase">Period:</span>
            <select 
              className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-bold cursor-pointer"
              value={filterMonth}
              onChange={(e) => setFilterMonth(e.target.value)}
            >
              <option value="ALL">All Months</option>
              {MONTHS.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <label className={`flex items-center space-x-2 px-4 py-2 border rounded-xl cursor-pointer transition-all text-sm font-black uppercase shadow-sm ${
            forcedType === 'INCOME' 
              ? 'bg-emerald-50 text-emerald-700 border-emerald-100 hover:bg-emerald-100' 
              : 'bg-indigo-50 text-indigo-700 border-indigo-100 hover:bg-indigo-100'
          }`}>
            <Upload size={16} />
            <span>Smart Import</span>
            <input type="file" accept=".csv" className="hidden" onChange={handleCsvUpload} />
          </label>
          <button 
            onClick={exportToCSV}
            className="flex items-center space-x-2 px-4 py-2 bg-slate-100 text-slate-700 border border-slate-200 rounded-xl hover:bg-slate-200 transition-all text-sm font-black uppercase shadow-sm"
          >
            <Download size={16} />
            <span>Export CSV</span>
          </button>
          <button 
            onClick={exportToPDF}
            className="flex items-center space-x-2 px-4 py-2 bg-slate-100 text-slate-700 border border-slate-200 rounded-xl hover:bg-slate-200 transition-all text-sm font-black uppercase shadow-sm"
          >
            <FileDown size={16} />
            <span>Export PDF</span>
          </button>
          <button 
            onClick={() => setIsModalOpen(true)}
            className={`flex items-center space-x-2 px-4 py-2 text-white rounded-xl font-black uppercase text-sm shadow-md transition-all active:scale-95 ${
              forcedType === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-slate-900 hover:bg-black'
            }`}
          >
            <Plus size={16} />
            <span>Add Entry</span>
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <div className="p-3 bg-amber-50 border-b border-amber-100 text-[9px] font-black text-amber-700 uppercase tracking-widest flex items-center space-x-2">
           <div className="w-1 h-1 bg-amber-500 rounded-full animate-pulse"></div>
           <span>Double-click any cell to edit details inline</span>
        </div>
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entity / Source</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Category</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Method</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Amount (ZAR)</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(t => (
              <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group animate-fadeIn">
                <td 
                  className="px-6 py-4 text-xs text-slate-500 font-bold cursor-pointer"
                  onDoubleClick={() => startEdit(t, 'date')}
                >
                  {editCell?.id === t.id && editCell.field === 'date' 
                    ? renderEditControl(t, 'date') 
                    : t.date}
                </td>
                <td 
                  className="px-6 py-4 cursor-pointer"
                  onDoubleClick={() => startEdit(t, 'entity')}
                >
                  {editCell?.id === t.id && editCell.field === 'entity' ? (
                    renderEditControl(t, 'entity')
                  ) : (
                    <div className="flex flex-col">
                      <span className="text-sm font-black text-slate-900 leading-none">{t.entity}</span>
                      <span className="text-[10px] text-slate-400 truncate max-w-[300px] mt-1">{t.description}</span>
                    </div>
                  )}
                </td>
                <td 
                  className="px-6 py-4 cursor-pointer"
                  onDoubleClick={() => startEdit(t, 'category')}
                >
                  {editCell?.id === t.id && editCell.field === 'category' ? (
                    renderEditControl(t, 'category')
                  ) : (
                    <span className="inline-flex items-center px-2 py-0.5 rounded-lg text-[9px] font-black border uppercase tracking-tighter bg-slate-50 text-slate-600">
                      {t.category}
                    </span>
                  )}
                </td>
                <td 
                  className="px-6 py-4 text-[10px] text-slate-400 font-black uppercase cursor-pointer"
                  onDoubleClick={() => startEdit(t, 'paymentMethod')}
                >
                  {editCell?.id === t.id && editCell.field === 'paymentMethod' 
                    ? renderEditControl(t, 'paymentMethod') 
                    : t.paymentMethod}
                </td>
                <td 
                  className={`px-6 py-4 text-sm font-black text-right cursor-pointer ${t.type === 'INCOME' ? 'text-emerald-600' : 'text-slate-900'}`}
                  onDoubleClick={() => startEdit(t, 'amount')}
                >
                  {editCell?.id === t.id && editCell.field === 'amount' ? (
                    renderEditControl(t, 'amount')
                  ) : (
                    `${t.type === 'INCOME' ? '+' : '-'} R${t.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}`
                  )}
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => onDelete(t.id)} className="p-1 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all">
                    <Trash2 size={16} />
                  </button>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-20 text-center">
                  <div className="flex flex-col items-center justify-center space-y-3 opacity-30">
                    <FileSpreadsheet size={48} />
                    <p className="text-sm font-black uppercase tracking-widest">No Records for {filterMonth === 'ALL' ? 'Selected View' : filterMonth}</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl animate-scaleIn">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-900 uppercase">Manual {formData.department} Entry</h3>
                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">Recording to Strategic Ledger</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 text-2xl font-light">&times;</button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Date</label>
                  <input type="date" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Category</label>
                  <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                    {DEPT_CATEGORIES[formData.department].map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Amount (ZAR)</label>
                  <input type="number" step="0.01" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-black" value={formData.amount} onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Method</label>
                  <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.paymentMethod} onChange={e => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}>
                    {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Entity (Vendor / Employee / Source)</label>
                <input type="text" placeholder="e.g. SAB, Kitchen Wages, Unit 5" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={formData.entity} onChange={e => setFormData({...formData, entity: e.target.value})} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase">Reference / Notes</label>
                <textarea className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium h-20 resize-none" placeholder="Reference details..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
              </div>
              <button type="submit" className={`w-full py-4 text-white rounded-xl font-black uppercase text-sm shadow-xl ${
                forcedType === 'INCOME' ? 'bg-emerald-600 shadow-emerald-100' : 'bg-slate-900 shadow-slate-100'
              }`}>Record Entry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TransactionManager;

import React, { useState, useEffect, useRef } from 'react';
import { Transaction, Category, PaymentMethod, TransactionType, Department } from '../types';
import { CATEGORIES, PAYMENT_METHODS, MONTHS, DEPARTMENTS, DEPT_CATEGORIES } from '../constants';
import { Plus, Upload, Search, Trash2, Filter, FileSpreadsheet, Wallet, TrendingUp, TrendingDown, ChevronRight, FileDown, Download, Check, X } from 'lucide-react';
import { jsPDF } from 'jspdf';
import 'jspdf-autotable';

interface Props {
  transactions: Transaction[];
  onAdd: (items: Transaction[]) => void;
  onDelete: (id: string) => void;
  onUpdate: (updated: Transaction) => void;
  forcedType?: TransactionType;
}

interface EditCell {
  id: string;
  field: keyof Transaction;
}

const TransactionManager: React.FC<Props> = ({ transactions, onAdd, onDelete, onUpdate, forcedType }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterMonth, setFilterMonth] = useState('ALL');

  const [editCell, setEditCell] = useState<EditCell | null>(null);
  const [editValue, setEditValue] = useState<any>(null);
  const inputRef = useRef<HTMLInputElement | HTMLSelectElement | null>(null);

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: forcedType || 'EXPENSE' as TransactionType,
    department: (forcedType === 'INCOME' ? 'REVENUE' : 'COGS') as Department | 'REVENUE',
    category: (forcedType === 'INCOME' ? 'POS Cash' : 'Food Costs') as Category,
    amount: 0,
    entity: '',
    description: '',
    paymentMethod: 'EFT' as PaymentMethod
  });

  useEffect(() => {
    if (forcedType === 'INCOME') {
      setFormData(prev => ({ ...prev, type: 'INCOME', department: 'REVENUE', category: 'POS Cash' }));
    } else {
      // Default new expense to COGS/Food
      setFormData(prev => ({ ...prev, type: 'EXPENSE', department: 'COGS', category: 'Food Costs' }));
    }
  }, [forcedType]);

  useEffect(() => {
    if (editCell && inputRef.current) {
      inputRef.current.focus();
    }
  }, [editCell]);

  const filtered = transactions.filter(t => {
    const matchesSearch = t.entity.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesMonth = filterMonth === 'ALL' || t.month === filterMonth;
    const matchesType = t.type === (forcedType || 'EXPENSE');
    // Removed activeDept filter to show unified expenditure
    return matchesSearch && matchesMonth && matchesType;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const startEdit = (transaction: Transaction, field: keyof Transaction) => {
    setEditCell({ id: transaction.id, field });
    setEditValue(transaction[field]);
  };

  const saveEdit = () => {
    if (!editCell) return;
    const original = transactions.find(t => t.id === editCell.id);
    if (original) {
      const updated = { ...original, [editCell.field]: editValue };
      if (editCell.field === 'date') {
        updated.month = (editValue as string).substring(0, 7);
      }
      // If category is edited, update department as well
      if (editCell.field === 'category') {
        for (const [dept, cats] of Object.entries(DEPT_CATEGORIES)) {
          if ((cats as string[]).includes(editValue as string)) {
            updated.department = dept as Department | 'REVENUE';
            break;
          }
        }
      }
      onUpdate(updated);
    }
    setEditCell(null);
    setEditValue(null);
  };

  const cancelEdit = () => {
    setEditCell(null);
    setEditValue(null);
  };

