import React, { useState, useRef } from 'react';
import { AppView } from '../types';
import { NAV_ITEMS } from '../constants';
import { Package, Upload, CheckCircle2 } from 'lucide-react';

interface SidebarProps {
  activeView: AppView;
  onNavigate: (view: AppView) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, onNavigate }) => {
  const [assetValue, setAssetValue] = useState<number | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAssetCsv = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const lines = text.split('\n');
      if (lines.length < 2) return;

      const header = lines[0].toLowerCase().split(',');
      // Try to find columns like 'value', 'total', 'cost', 'price', 'asset'
      const valueIdx = header.findIndex(h => 
        h.includes('value') || 
        h.includes('total') || 
        h.includes('cost') || 
        h.includes('asset')
      );

      let total = 0;
      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        const parts = line.split(',');
        if (valueIdx !== -1 && parts[valueIdx]) {
          const val = parseFloat(parts[valueIdx].replace(/[^\d.-]/g, ''));
          if (!isNaN(val)) total += val;
        }
      }

      setAssetValue(total);
      setIsImporting(false);
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <aside className="w-64 bg-white border-r border-slate-200 flex flex-col h-full hidden md:flex">
      <div className="p-6">
        <div className="flex items-center space-x-3 mb-8">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg">R</div>
          <span className="text-lg font-bold text-slate-800">AuditPro</span>
        </div>

        {/* ASSET VALUE WIDGET */}
        <div className="mb-6 px-2">
          <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 group transition-all">
            <div className="flex justify-between items-center mb-2">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Food and Bev stock hold</span>
              <Package size={14} className="text-indigo-500" />
            </div>

            {assetValue !== null ? (
              <div className="animate-fadeIn">
                <p className="text-lg font-black text-slate-900 leading-tight">R{assetValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
                <div className="flex items-center mt-1 text-emerald-600 space-x-1">
                  <CheckCircle2 size={10} />
                  <span className="text-[9px] font-bold uppercase">Verified Value</span>
                </div>
              </div>
            ) : (
              <p className="text-xs font-bold text-slate-400 italic">No Data Loaded</p>
            )}

            <label className="mt-3 flex items-center justify-center space-x-2 w-full py-2 bg-white border border-slate-200 rounded-xl text-[10px] font-black uppercase text-indigo-600 cursor-pointer hover:bg-indigo-50 hover:border-indigo-200 transition-all shadow-sm">
              <Upload size={12} />
              <span>{isImporting ? 'Processing...' : 'Current Asset Value'}</span>
              <input 
                ref={fileInputRef}
                type="file" 
                accept=".csv" 
                className="hidden" 
                onChange={handleAssetCsv} 
                disabled={isImporting}
              />
            </label>
          </div>
        </div>

        <nav className="space-y-1">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id as AppView)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                activeView === item.id
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm'
                  : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
              }`}
            >
              {item.icon}
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          ))}
        </nav>
      </div>

      <div className="mt-auto p-6 border-t border-slate-100">
        <div className="bg-slate-900 rounded-2xl p-4 text-white">
          <p className="text-xs text-slate-400 mb-1">Current Quarter</p>
          <p className="text-sm font-semibold mb-3">Q3 - Q4 2025</p>
          <div className="w-full bg-slate-700 rounded-full h-1.5 mb-1">
            <div className="bg-indigo-500 h-1.5 rounded-full" style={{ width: '80%' }}></div>
          </div>
          <p className="text-[10px] text-slate-400 text-right">80% Reconciled</p>
        </div>
      </div>
    </aside>
  );
};

