            R{loans.reduce((acc, l) => acc + l.balance, 0).toLocaleString()}
          </p>
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Audited & Verified</span>
        </div>
      </div>
    </div>
  );
};

