{
  "name": "Chaos Audit Motherfuckers",
  "description": "A high-precision restaurant financial management and forensic audit system with detailed income/expense tracking, CSV import capabilities, and loan account management.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, AppView, LoanAccount, TransactionType } from './types';
import { NAV_ITEMS, MONTHS } from './constants';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TransactionManager from './components/TransactionManager';
import LoanManager from './components/LoanManager';
import SupplierManager from './components/SupplierManager';
import IncomeSummary from './components/IncomeSummary';
import PLStatement from './components/PLStatement';

const INITIAL_TRANSACTIONS: Transaction[] = [];

const INITIAL_LOANS: LoanAccount[] = [
  {
    id: 'loan-2',
    name: 'Loan Account Anthony Landon',
    principal: 100000,
    interestRate: 12.0,
    startDate: '2025-06-15',
    balance: 85000,
    history: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('DASHBOARD');
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('resto_transactions');
    return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [loans, setLoans] = useState<LoanAccount[]>(() => {
    const saved = localStorage.getItem('resto_loans');
    return saved ? JSON.parse(saved) : INITIAL_LOANS;
  });

  // Calculate Recurring / Permanent Monthly Expenses
  const allTransactions = useMemo(() => {
    const recurring: Transaction[] = [];

    MONTHS.forEach(month => {
      // 1. Marketing & Communication
      recurring.push({
        id: `auto-mkt-${month}`,
        date: `${month}-01`,
        type: 'EXPENSE',
        department: 'Direct Operating',
        category: 'Marketing & Advertising',
        amount: 1500,
        entity: 'Marketing & Comm (Monthly)',
        description: 'Auto-generated permanent monthly expense',
        paymentMethod: 'EFT',
        month: month
      });

      // 2. POS Rental
      recurring.push({
        id: `auto-pos-${month}`,
        date: `${month}-01`,
        type: 'EXPENSE',
        department: 'Direct Operating',
        category: 'Technology',
        amount: 1750,
        entity: 'POS Rental (Monthly)',
        description: 'Auto-generated permanent monthly expense',
        paymentMethod: 'EFT',
        month: month
      });

      // 3. Banking Fees (5% of POS Card Sales)
      const monthlyCardSales = transactions
        .filter(t => t.month === month && t.type === 'INCOME' && t.category === 'POS Card')
        .reduce((sum, t) => sum + t.amount, 0);

      const bankingFeeAmount = monthlyCardSales * 0.05;

      if (bankingFeeAmount > 0) {
        recurring.push({
          id: `auto-bank-${month}`,
          date: `${month}-28`, // Typically processed at month end
          type: 'EXPENSE',
          department: 'G&A',
          category: 'Bank Fees',
          amount: bankingFeeAmount,
          entity: 'Banking Fees (5% Card Sales)',
          description: `Calculated from R${monthlyCardSales.toLocaleString()} card revenue`,
          paymentMethod: 'EFT',
          month: month
        });
      }
    });

    return [...transactions, ...recurring];
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('resto_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('resto_loans', JSON.stringify(loans));
  }, [loans]);

  const addTransactions = (newItems: Transaction[]) => {
    setTransactions(prev => [...prev, ...newItems]);
  };

  const deleteTransaction = (id: string) => {
    // Only allow deleting non-auto transactions
    if (id.startsWith('auto-')) return;
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const clearTransactions = (type: TransactionType, month?: string) => {
    setTransactions(prev => prev.filter(t => {
      // Keep other types
      if (t.type !== type) return true;
      // Keep auto-generated items
      if (t.id.startsWith('auto-')) return true;
      // If month specified and matches, remove it
      if (month && month !== 'ALL') {
        return t.month !== month;
      }
      // If no month specified, clear all for this type
      return false;
    }));
  };

  const updateTransaction = (updated: Transaction) => {
    // Only allow updating non-auto transactions
    if (updated.id.startsWith('auto-')) return;
    setTransactions(prev => prev.map(t => t.id === updated.id ? updated : t));
  };

  const updateLoan = (updatedLoan: LoanAccount) => {
    setLoans(prev => prev.map(l => l.id === updatedLoan.id ? updatedLoan : l));
  };

  const renderContent = () => {
    switch (view) {
      case 'DASHBOARD':
        return <Dashboard transactions={allTransactions} loans={loans} onNavigate={setView} />;
      case 'INCOME':
        return (
          <TransactionManager 
            transactions={allTransactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            onUpdate={updateTransaction}
            onClear={(month) => clearTransactions('INCOME', month)}
            forcedType="INCOME"
          />
        );
      case 'INCOME_SUMMARY':
        return <IncomeSummary transactions={allTransactions} />;
      case 'EXPENDITURE':
        return (
          <TransactionManager 
            transactions={allTransactions} 
            onAdd={addTransactions} 
            onDelete={deleteTransaction} 
            onUpdate={updateTransaction}
            onClear={(month) => clearTransactions('EXPENSE', month)}
            forcedType="EXPENSE"
          />
        );
      case 'SUPPLIERS':
        return <SupplierManager transactions={allTransactions} />;
      case 'LOANS':
        return <LoanManager loans={loans} onUpdate={updateLoan} onTransactionAdd={addTransactions} />;
      case 'PL_STATEMENT':
        return <PLStatement transactions={allTransactions} loans={loans} />;
      default:
        return <Dashboard transactions={allTransactions} loans={loans} onNavigate={setView} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar 
        activeView={view} 
        onNavigate={setView} 
        transactions={allTransactions} 
        loans={loans} 
      />
      <main className="flex-1 overflow-y-auto p-4 md:p-8">
        <div className="max-w-7xl mx-auto space-y-6">
          <header className="flex justify-between items-center pb-4 border-b border-slate-200">
            <div>
              <h1 className="text-2xl font-bold text-slate-900 tracking-tighter uppercase">Chaos Audit Motherfuckers</h1>
              <p className="text-slate-500 text-xs font-black uppercase tracking-widest mt-0.5">Financial Annihilation Suite</p>
            </div>
            <div className="flex items-center space-x-2 text-xs font-medium uppercase tracking-wider text-slate-400">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span>Live Database Connected</span>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { AppView, Transaction, LoanAccount } from '../types';
import { NAV_ITEMS, MONTHS } from '../constants';
import { Package, Upload, CheckCircle2, HardDrive, AlertCircle, X, Check } from 'lucide-react';

interface SidebarProps {
  activeView: AppView;
  onNavigate: (view: AppView) => void;
  transactions: Transaction[];
  loans: LoanAccount[];
}

interface ChecklistItem {
  id: string;
  label: string;
  status: 'COMPLETED' | 'INCOMPLETE';
  description: string;
  actionNeeded: string;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, onNavigate, transactions, loans }) => {
  const [stockValue, setStockValue] = useState<number | null>(() => {
    const saved = localStorage.getItem('resto_stock_value');
    return saved ? parseFloat(saved) : null;
  });
  const [equipmentValue, setEquipmentValue] = useState<number | null>(() => {
    const saved = localStorage.getItem('resto_equip_value');
    return saved ? parseFloat(saved) : null;
  });

  const [isImportingStock, setIsImportingStock] = useState(false);
  const [isImportingEquip, setIsImportingEquip] = useState(false);
  const [editingField, setEditingField] = useState<'stock' | 'equip' | null>(null);
  const [tempValue, setTempValue] = useState('');
  const [isChecklistOpen, setIsChecklistOpen] = useState(false);

  const stockInputRef = useRef<HTMLInputElement>(null);
  const equipInputRef = useRef<HTMLInputElement>(null);
  const editInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (stockValue !== null) localStorage.setItem('resto_stock_value', stockValue.toString());
  }, [stockValue]);

  useEffect(() => {
    if (equipmentValue !== null) localStorage.setItem('resto_equip_value', equipmentValue.toString());
  }, [equipmentValue]);

  useEffect(() => {
    if (editingField && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingField]);

  // Forensic Checklist Logic
  const checklist = useMemo((): ChecklistItem[] => {
    const items: ChecklistItem[] = [];

    // 1. Monthly Revenue Coverage
    const monthsWithIncome = new Set(transactions.filter(t => t.type === 'INCOME').map(t => t.month));
    const allMonthsCoveredIncome = MONTHS.every(m => monthsWithIncome.has(m));
    items.push({
      id: 'revenue_coverage',
      label: 'Monthly Revenue Journals',
      status: allMonthsCoveredIncome ? 'COMPLETED' : 'INCOMPLETE',
      description: 'Income recorded for all active months in the cycle.',
      actionNeeded: `Missing income for: ${MONTHS.filter(m => !monthsWithIncome.has(m)).join(', ')}`
    });

    // 2. Monthly Expense Coverage
    const monthsWithExpense = new Set(transactions.filter(t => t.type === 'EXPENSE').map(t => t.month));
    const allMonthsCoveredExpense = MONTHS.every(m => monthsWithExpense.has(m));
    items.push({
      id: 'expense_coverage',
      label: 'Monthly Expense Journals',
      status: allMonthsCoveredExpense ? 'COMPLETED' : 'INCOMPLETE',
      description: 'Expenses recorded for all active months in the cycle.',
      actionNeeded: `Missing expenses for: ${MONTHS.filter(m => !monthsWithExpense.has(m)).join(', ')}`
    });

    // 3. F&B Stock Valuation
    items.push({
      id: 'stock_valuation',
      label: 'Food & Bev Stock Audit',
      status: stockValue !== null && stockValue > 0 ? 'COMPLETED' : 'INCOMPLETE',
      description: 'A current audited stock valuation for F&B inventory.',
      actionNeeded: 'Double-click "F&B Stock Hold" or import a Stock CSV.'
    });

    // 4. Equipment Asset Audit
    items.push({
      id: 'equip_valuation',
      label: 'Equipment Asset Register',
      status: equipmentValue !== null && equipmentValue > 0 ? 'COMPLETED' : 'INCOMPLETE',
      description: 'A verified valuation of kitchen and front-of-house equipment.',
      actionNeeded: 'Double-click "Equipment Assets" or import an Equipment CSV.'
    });

    // 5. Loan Reconciliation
    const allLoansReconciled = loans.every(l => l.history.length > 0);
    items.push({
      id: 'loan_recon',
      label: 'Debt Account Reconciliation',
      status: allLoansReconciled ? 'COMPLETED' : 'INCOMPLETE',
      description: 'Detailed payment and interest journals for all debt facilities.',
      actionNeeded: 'At least one journal entry required for every loan account.'
    });

    // 6. Categorization Hygiene
    const uncategorizedCount = transactions.filter(t => t.category === 'Other').length;
    items.push({
      id: 'hygiene',
      label: 'Categorization Hygiene',
      status: uncategorizedCount === 0 ? 'COMPLETED' : 'INCOMPLETE',
      description: 'All ledger entries correctly assigned to specific forensic categories.',
      actionNeeded: `${uncategorizedCount} entries are currently under "Other". Review Income/Expense tabs.`
    });

    return items;
  }, [transactions, loans, stockValue, equipmentValue]);

  const compliancePercentage = useMemo(() => {
    const completed = checklist.filter(i => i.status === 'COMPLETED').length;
    return Math.round((completed / checklist.length) * 100);
  }, [checklist]);

  const parseAssetCsv = (text: string): number => {
    const lines = text.split('\n');
    if (lines.length < 2) return 0;
    const header = lines[0].toLowerCase().split(',');
    const valueIdx = header.findIndex(h => 
      h.includes('value') || h.includes('total') || h.includes('cost') || h.includes('asset') || h.includes('amount')
    );
    let total = 0;
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;
      const parts = line.split(',');
      if (valueIdx !== -1 && parts[valueIdx]) {
        const val = parseFloat(parts[valueIdx].replace(/[^\d.-]/g, ''));
        if (!isNaN(val)) total += val;
      }
    }
    return total;
  };

  const handleStockCsv = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImportingStock(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      setStockValue(parseAssetCsv(event.target?.result as string));
      setIsImportingStock(false);
      if (stockInputRef.current) stockInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const handleEquipCsv = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImportingEquip(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      setEquipmentValue(parseAssetCsv(event.target?.result as string));
      setIsImportingEquip(false);
      if (equipInputRef.current) equipInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  const handleEdit = (field: 'stock' | 'equip', currentVal: number | null) => {
    setEditingField(field);
    setTempValue(currentVal?.toString() || '0');
  };

  const saveManualValue = () => {
    const val = parseFloat(tempValue);
    if (!isNaN(val)) {
      if (editingField === 'stock') setStockValue(val);
      if (editingField === 'equip') setEquipmentValue(val);
    }
    setEditingField(null);
  };

  return (
    <>
      <aside className="w-64 bg-white border-r border-slate-200 flex flex-col h-full hidden md:flex">
        <div className="p-6 overflow-y-auto scrollbar-hide">
          <div className="flex items-center space-x-3 mb-8">
            <div className="w-8 h-8 bg-indigo-900 rounded-lg flex items-center justify-center text-white font-black text-lg">C</div>
            <span className="text-lg font-black text-slate-800 tracking-tighter uppercase">Chaos Audit</span>
          </div>

          <div className="space-y-4 mb-8">
            {/* STOCK VALUE WIDGET */}
            <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 transition-all">
              <div className="flex justify-between items-center mb-2">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">F&B Stock Hold</span>
                <Package size={12} className="text-indigo-500" />
              </div>

              <div onDoubleClick={() => handleEdit('stock', stockValue)} className="cursor-pointer group relative">
                {editingField === 'stock' ? (
                  <input
                    ref={editInputRef}
                    type="number"
                    className="w-full bg-white border border-indigo-400 rounded px-1 py-0.5 text-md font-black text-slate-900 outline-none"
                    value={tempValue}
                    onChange={(e) => setTempValue(e.target.value)}
                    onBlur={saveManualValue}
                    onKeyDown={(e) => e.key === 'Enter' && saveManualValue()}
                  />
                ) : stockValue !== null ? (
                  <div className="animate-fadeIn">
                    <p className="text-md font-black text-slate-900 leading-tight group-hover:text-indigo-600 transition-colors">
                      R{stockValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </p>
                    <div className="flex items-center mt-0.5 text-emerald-600 space-x-1">
                      <CheckCircle2 size={10} />
                      <span className="text-[8px] font-bold uppercase">Audited</span>
                    </div>
                  </div>
                ) : (
                  <p className="text-[10px] font-bold text-slate-400 italic">No Data (Dbl-Click)</p>
                )}
              </div>

              <label className="mt-3 flex items-center justify-center space-x-2 w-full py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase text-indigo-600 cursor-pointer hover:bg-indigo-50 transition-all shadow-sm">
                <Upload size={10} />
                <span>{isImportingStock ? '...' : 'Import Stock CSV'}</span>
                <input ref={stockInputRef} type="file" accept=".csv" className="hidden" onChange={handleStockCsv} disabled={isImportingStock} />
              </label>
            </div>

            {/* EQUIPMENT VALUE WIDGET */}
            <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 transition-all">
              <div className="flex justify-between items-center mb-2">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Equipment Assets</span>
                <HardDrive size={12} className="text-amber-500" />
              </div>

              <div onDoubleClick={() => handleEdit('equip', equipmentValue)} className="cursor-pointer group relative">
                {editingField === 'equip' ? (
                  <input
                    ref={editInputRef}
                    type="number"
                    className="w-full bg-white border border-indigo-400 rounded px-1 py-0.5 text-md font-black text-slate-900 outline-none"
                    value={tempValue}
                    onChange={(e) => setTempValue(e.target.value)}
                    onBlur={saveManualValue}
                    onKeyDown={(e) => e.key === 'Enter' && saveManualValue()}
                  />
                ) : equipmentValue !== null ? (
                  <div className="animate-fadeIn">
                    <p className="text-md font-black text-slate-900 leading-tight group-hover:text-amber-600 transition-colors">
                      R{equipmentValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </p>
                    <div className="flex items-center mt-0.5 text-emerald-600 space-x-1">
                      <CheckCircle2 size={10} />
                      <span className="text-[8px] font-bold uppercase">Verified</span>
                    </div>
                  </div>
                ) : (
                  <p className="text-[10px] font-bold text-slate-400 italic">No Data (Dbl-Click)</p>
                )}
              </div>

              <label className="mt-3 flex items-center justify-center space-x-2 w-full py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase text-amber-600 cursor-pointer hover:bg-amber-50 transition-all shadow-sm">
                <Upload size={10} />
                <span>{isImportingEquip ? '...' : 'Import Equip CSV'}</span>
                <input ref={equipInputRef} type="file" accept=".csv" className="hidden" onChange={handleEquipCsv} disabled={isImportingEquip} />
              </label>
